import React from 'react';
import { DigestConfig, ExperienceLevel, Topic } from '../types';
import { AVAILABLE_TOPICS } from '../constants';
import { Sparkles, Layers, RefreshCw } from 'lucide-react';

interface DigestConfiguratorProps {
  config: DigestConfig;
  setConfig: React.Dispatch<React.SetStateAction<DigestConfig>>;
  onGenerate: () => void;
  isLoading: boolean;
}

const DigestConfigurator: React.FC<DigestConfiguratorProps> = ({ config, setConfig, onGenerate, isLoading }) => {

  const toggleTopic = (topic: Topic) => {
    setConfig(prev => {
      // If selecting Random, clear others. If selecting others, clear Random.
      if (topic === 'Random/Surprise Me') {
        return { ...prev, topics: ['Random/Surprise Me'] };
      }

      const newTopics = prev.topics.filter(t => t !== 'Random/Surprise Me');
      if (prev.topics.includes(topic)) {
        return { ...prev, topics: newTopics.filter(t => t !== topic) };
      } else {
        return { ...prev, topics: [...newTopics, topic] };
      }
    });
  };

  const handleLevelChange = (level: ExperienceLevel) => {
    setConfig(prev => ({ ...prev, level }));
  };

  return (
    <div className="bg-white rounded-2xl p-6 md:p-8 shadow-sm border border-stone-200 max-w-3xl mx-auto mb-12">
      <div className="flex flex-col md:flex-row gap-8">

        {/* Experience Level */}
        <div className="flex-shrink-0 md:w-1/3 space-y-3">
          <label className="flex items-center text-sm font-semibold text-stone-900 uppercase tracking-wide">
            <Layers className="w-4 h-4 mr-2 text-stone-400" />
            Experience Level
          </label>
          <div className="flex flex-col gap-2">
            {(['Beginner-Mid', 'Mid-Senior'] as ExperienceLevel[]).map((level) => (
              <button
                key={level}
                onClick={() => handleLevelChange(level)}
                className={`px-4 py-3 text-left rounded-lg text-sm font-medium transition-all ${
                  config.level === level 
                    ? 'bg-stone-900 text-white shadow-md' 
                    : 'bg-stone-50 text-stone-600 hover:bg-stone-100'
                }`}
              >
                {level === 'Beginner-Mid' ? 'Foundations (Jr-Mid)' : 'Strategy & Leadership (Sr+)'}
              </button>
            ))}
          </div>
        </div>

        {/* Topics */}
        <div className="flex-grow space-y-3">
          <label className="flex items-center text-sm font-semibold text-stone-900 uppercase tracking-wide">
            <Sparkles className="w-4 h-4 mr-2 text-stone-400" />
            Curate For
          </label>
          <div className="flex flex-wrap gap-2">
            {AVAILABLE_TOPICS.map((topic) => (
              <button
                key={topic}
                onClick={() => toggleTopic(topic)}
                className={`px-3 py-2 rounded-full text-xs md:text-sm font-medium border transition-all ${
                  config.topics.includes(topic)
                    ? 'bg-stone-100 border-stone-400 text-stone-900 shadow-sm'
                    : 'bg-white border-stone-200 text-stone-500 hover:border-stone-300'
                }`}
              >
                {topic}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="mt-8 flex justify-end">
        <button
          onClick={onGenerate}
          disabled={isLoading || config.topics.length === 0}
          className={`
            flex items-center px-8 py-3 rounded-full font-serif font-bold text-lg shadow-lg transition-transform active:scale-95
            ${isLoading 
              ? 'bg-stone-200 text-stone-400 cursor-not-allowed' 
              : 'bg-charcoal text-white hover:bg-stone-800'
            }
          `}
        >
          {isLoading ? (
            <>Synthesizing...</>
          ) : (
            <>
              Generate Digest
              <RefreshCw className="ml-2 w-4 h-4" />
            </>
          )}
        </button>
      </div>
    </div>
  );
};

export default DigestConfigurator;

import React, { useState } from 'react';
import { Search, ArrowRight } from 'lucide-react';

interface UrlAnalyzerProps {
  onAnalyze: (url: string) => void;
  isLoading: boolean;
}

const UrlAnalyzer: React.FC<UrlAnalyzerProps> = ({ onAnalyze, isLoading }) => {
  const [url, setUrl] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (url.trim()) {
      onAnalyze(url);
    }
  };

  return (
    <div className="bg-stone-900 text-cream rounded-2xl p-6 md:p-8 max-w-3xl mx-auto shadow-xl">
      <h3 className="font-serif text-xl mb-4 text-white">Instant Summary</h3>
      <p className="text-stone-400 text-sm mb-6">
        Paste any URL (Medium article, YouTube video, NNGroup case study) and let our AI agent analyze it for you.
      </p>

      <form onSubmit={handleSubmit} className="relative">
        <div className="relative flex items-center">
          <Search className="absolute left-4 w-5 h-5 text-stone-500" />
          <input
            type="url"
            placeholder="https://..."
            value={url}
            onChange={(e) => setUrl(e.target.value)}
            disabled={isLoading}
            required
            className="w-full pl-12 pr-14 py-4 bg-stone-800 border border-stone-700 rounded-xl text-white placeholder-stone-500 focus:outline-none focus:ring-2 focus:ring-stone-600 transition-all"
          />
          <button
            type="submit"
            disabled={isLoading || !url}
            className="absolute right-2 p-2 bg-cream text-stone-900 rounded-lg hover:bg-white disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            <ArrowRight className="w-5 h-5" />
          </button>
        </div>
      </form>
    </div>
  );
};

export default UrlAnalyzer;

import React, { useState, useEffect } from 'react';
import { DigestConfig, Article, DigestHistoryItem } from './types';
import { fetchLiveDigest, analyzeUrl } from './services/geminiService';
import DigestConfigurator from './components/DigestConfigurator';
import ArticleCard from './components/ArticleCard';
import UrlAnalyzer from './components/UrlAnalyzer';
import SkeletonLoader from './components/SkeletonLoader';
import { Newspaper, History, Clock, ArrowLeft } from 'lucide-react';

// Main App Component
function App() {
  // State
  const [view, setView] = useState<'dashboard' | 'history' | 'result'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [articles, setArticles] = useState<Article[]>([]);
  const [history, setHistory] = useState<DigestHistoryItem[]>([]);

  // Configuration State
  const [config, setConfig] = useState<DigestConfig>({
    level: 'Mid-Senior',
    topics: ['Random/Surprise Me']
  });

  // History State persistence
  useEffect(() => {
    const saved = localStorage.getItem('ddd_history');
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse history", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('ddd_history', JSON.stringify(history));
  }, [history]);

  // Handlers
  const handleGenerateDigest = async () => {
    setLoading(true);
    setView('result');
    setArticles([]); // Clear previous

    try {
      const results = await fetchLiveDigest(config);
      setArticles(results);

      // Save to history
      const historyItem: DigestHistoryItem = {
        id: crypto.randomUUID(),
        timestamp: Date.now(),
        config: config,
        articles: results,
        type: 'feed'
      };
      setHistory(prev => [historyItem, ...prev]);
    } catch (err) {
      console.error("Failed to generate digest", err);
      // In a real app, show toast. Here fallback logic in service should prevent full crash.
    } finally {
      setLoading(false);
    }
  };

  const handleAnalyzeUrl = async (url: string) => {
    setLoading(true);
    setView('result');
    setArticles([]);

    try {
      const result = await analyzeUrl(url);
      setArticles([result]);

      const historyItem: DigestHistoryItem = {
        id: crypto.randomUUID(),
        timestamp: Date.now(),
        config: { level: config.level, topics: [] }, // Empty topics for URL
        articles: [result],
        type: 'url'
      };
      setHistory(prev => [historyItem, ...prev]);
    } catch (err) {
      console.error("Failed to analyze URL", err);
    } finally {
      setLoading(false);
    }
  };

  const restoreHistoryItem = (item: DigestHistoryItem) => {
    setArticles(item.articles);
    setView('result');
  };

  // Render Helpers
  const renderHeader = () => (
    <header className="py-8 md:py-12 border-b border-stone-200 mb-8 bg-cream sticky top-0 z-50 bg-opacity-95 backdrop-blur-sm">
      <div className="max-w-6xl mx-auto px-4 flex justify-between items-center">
        <div className="cursor-pointer" onClick={() => setView('dashboard')}>
          <h1 className="font-serif text-3xl md:text-5xl font-bold text-charcoal tracking-tight">
            Daily Design Digest
          </h1>
          <p className="text-stone-500 mt-2 font-sans text-sm md:text-base tracking-wide">
            Curated intelligence for product people.
          </p>
        </div>

        <button 
          onClick={() => setView(view === 'history' ? 'dashboard' : 'history')}
          className="p-3 rounded-full hover:bg-stone-200 transition-colors text-stone-700"
          aria-label="History"
        >
          {view === 'history' ? <ArrowLeft /> : <History />}
        </button>
      </div>
    </header>
  );

  const renderDashboard = () => (
    <div className="space-y-16 animate-in fade-in duration-500">
      <section>
        <h2 className="text-center font-serif text-2xl text-stone-800 mb-8 italic">
          Configure today's briefing
        </h2>
        <DigestConfigurator 
          config={config} 
          setConfig={setConfig} 
          onGenerate={handleGenerateDigest} 
          isLoading={loading}
        />
      </section>

      <section className="border-t border-stone-200 pt-16">
        <UrlAnalyzer onAnalyze={handleAnalyzeUrl} isLoading={loading} />
      </section>
    </div>
  );

  const renderResults = () => (
    <div className="animate-in slide-in-from-bottom-4 duration-500">
      <div className="mb-8 flex items-center justify-between">
        <button 
          onClick={() => setView('dashboard')}
          className="flex items-center text-stone-500 hover:text-stone-900 transition-colors font-medium"
        >
          <ArrowLeft className="w-4 h-4 mr-2" />
          Back to Dashboard
        </button>
        <span className="text-stone-400 text-sm font-serif italic">
          {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}
        </span>
      </div>

      {loading ? (
        <SkeletonLoader message={`Synthesizing ${config.level === 'Mid-Senior' ? 'Strategic' : 'Foundational'} Insights...`} />
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pb-20">
          {articles.map((article) => (
            <ArticleCard key={article.id} article={article} />
          ))}
        </div>
      )}
    </div>
  );

  const renderHistory = () => (
    <div className="max-w-3xl mx-auto pb-20 animate-in fade-in duration-300">
      <h2 className="font-serif text-3xl mb-8 text-charcoal">Archive</h2>
      {history.length === 0 ? (
        <div className="text-center py-20 bg-white rounded-2xl border border-stone-200 border-dashed">
          <Newspaper className="w-12 h-12 text-stone-300 mx-auto mb-4" />
          <p className="text-stone-500">No digests generated yet.</p>
        </div>
      ) : (
        <div className="space-y-4">
          {history.map((item) => (
            <div 
              key={item.id}
              onClick={() => restoreHistoryItem(item)}
              className="bg-white p-6 rounded-xl border border-stone-200 hover:border-stone-400 hover:shadow-md cursor-pointer transition-all flex justify-between items-center group"
            >
              <div>
                <div className="flex items-center text-xs text-stone-400 mb-2 uppercase tracking-wider">
                  <Clock className="w-3 h-3 mr-1" />
                  {new Date(item.timestamp).toLocaleString()}
                  {item.type === 'url' && <span className="ml-2 bg-stone-100 text-stone-600 px-2 rounded-full">URL Analysis</span>}
                </div>
                <h3 className="font-serif text-lg text-stone-800 group-hover:text-charcoal font-medium">
                  {item.type === 'url' 
                    ? item.articles[0]?.title || 'Analyzed URL' 
                    : `${item.articles.length} Articles • ${item.config.level}`}
                </h3>
                {item.type === 'feed' && (
                  <div className="flex gap-2 mt-2">
                    {item.config.topics.map(t => (
                      <span key={t} className="text-xs bg-stone-50 px-2 py-1 rounded-md text-stone-500">
                        {t}
                      </span>
                    ))}
                  </div>
                )}
              </div>
              <ArrowLeft className="rotate-180 text-stone-300 group-hover:text-stone-900 transition-colors" />
            </div>
          ))}
        </div>
      )}
    </div>
  );

  return (
    <div className="min-h-screen bg-cream font-sans text-charcoal selection:bg-stone-200 selection:text-black">
      {renderHeader()}

      <main className="max-w-6xl mx-auto px-4">
        {view === 'dashboard' && renderDashboard()}
        {view === 'result' && renderResults()}
        {view === 'history' && renderHistory()}
      </main>
    </div>
  );
}

export default App;

export type ExperienceLevel = 'Beginner-Mid' | 'Mid-Senior';

export type Topic = 
  | 'Product Thinking' 
  | 'AI in UX' 
  | 'Visual Design' 
  | 'Strategy' 
  | 'Design Systems' 
  | 'Research' 
  | 'Random/Surprise Me';

export interface Article {
  id: string;
  title: string;
  author: string;
  source: string;
  type: 'Article' | 'Video';
  category: string;
  url: string;
  summary: string[];
  insights: string[];
  application_tips: string[];
}

export interface DigestConfig {
  level: ExperienceLevel;
  topics: Topic[];
}

export interface DigestHistoryItem {
  id: string;
  timestamp: number;
  config: DigestConfig;
  articles: Article[];
  type: 'feed' | 'url'; // Whether it was generated from feed or single URL
}

export interface UserPreferences {
  likedArticles: Article[];
  dislikedArticles: Article[];
}

import { GoogleGenAI, Type } from "@google/genai";
import { Article, DigestConfig, ExperienceLevel, Topic, UserPreferences } from "../types";
import { FALLBACK_ARTICLES } from "../constants";

// 1. Initialize API
const apiKey = process.env.API_KEY || ''; 
// Note: In a real app, we check if key exists. 
// The prompt says "Assume this variable is pre-configured...".
const ai = new GoogleGenAI({ apiKey });

const MODEL_NAME = 'gemini-2.5-flash-preview-09-2025';

// 2. Define Response Schema
// We define the schema for a single article and a list of articles to ensure strict JSON output.
const articleSchema = {
  type: Type.OBJECT,
  properties: {
    id: { type: Type.STRING },
    title: { type: Type.STRING },
    author: { type: Type.STRING },
    source: { type: Type.STRING },
    type: { type: Type.STRING, enum: ["Article", "Video"] },
    category: { type: Type.STRING },
    url: { type: Type.STRING },
    summary: { type: Type.ARRAY, items: { type: Type.STRING } },
    insights: { type: Type.ARRAY, items: { type: Type.STRING } },
    application_tips: { type: Type.ARRAY, items: { type: Type.STRING } }
  },
  required: ["id", "title", "author", "source", "type", "category", "url", "summary", "insights", "application_tips"]
};

const digestSchema = {
  type: Type.ARRAY,
  items: articleSchema
};

/**
 * Helper to clean JSON string if the model returns markdown code blocks
 */
const cleanJsonString = (str: string): string => {
  let cleaned = str.trim();
  if (cleaned.startsWith('```json')) {
    cleaned = cleaned.replace(/^```json/, '').replace(/```$/, '');
  } else if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```/, '').replace(/```$/, '');
  }
  return cleaned;
};

/**
 * Helper to construct preference string
 */
const getPreferenceContext = (prefs?: UserPreferences): string => {
  if (!prefs) return "";

  let context = "";
  if (prefs.likedArticles.length > 0) {
    const likedTitles = prefs.likedArticles.slice(0, 5).map(a => `"${a.title}" (${a.category})`).join(", ");
    context += `USER FEEDBACK - POSITIVE: The user previously found these articles helpful: ${likedTitles}. Prioritize similar topics, sources, or depth.\n`;
  }

  if (prefs.dislikedArticles.length > 0) {
    const dislikedTitles = prefs.dislikedArticles.slice(0, 5).map(a => `"${a.title}"`).join(", ");
    context += `USER FEEDBACK - NEGATIVE: The user disliked these articles: ${dislikedTitles}. Avoid similar content.\n`;
  }

  return context;
};

/**
 * Attempt 1: Search-Enabled Generation
 */
async function generateWithSearch(config: DigestConfig, prefs?: UserPreferences): Promise<Article[]> {
  const { level, topics } = config;

  const topicsStr = topics.includes('Random/Surprise Me') 
    ? "trending Product Design, UX Strategy, and UI Engineering topics"
    : topics.join(", ");

  const preferenceContext = getPreferenceContext(prefs);

  const prompt = `
    ACT AS: A Lead Product Designer.
    TASK: Active Web Search. Find 4 unique, high-quality, recent (last 6 months) articles or videos.
    TARGET AUDIENCE LEVEL: ${level}.
    TOPICS: ${topicsStr}.
    SOURCES TO SEARCH: UX Collective, Nielsen Norman Group, Smashing Magazine, A List Apart, The Futur, Growth.design, Reforge, Linear Blog, Figma Blog.

    ${preferenceContext}

    OUTPUT FORMAT: Return a JSON array of 4 Article objects.
    CRITICAL: In the 'application_tips' section, explain exactly 'How I can apply these learnings myself'. Be specific.

    The JSON structure must match this schema:
    [
      {
        "id": "uuid",
        "title": "Title",
        "author": "Author",
        "source": "Source Name",
        "type": "Article" | "Video",
        "category": "Topic Category",
        "url": "URL found",
        "summary": ["para1", "para2", "para3"],
        "insights": ["insight1", "insight2", "insight3", "insight4", "insight5"],
        "application_tips": ["tip1", "tip2", "tip3", "tip4", "tip5"]
      }
    ]
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: digestSchema,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No text returned from Search generation");

    const parsed = JSON.parse(cleanJsonString(text));
    return parsed as Article[];
  } catch (error) {
    console.warn("Attempt 1 (Search) failed:", error);
    throw error;
  }
}

/**
 * Attempt 2: Knowledge Base Generation (No Search)
 */
async function generateFromKnowledgeBase(config: DigestConfig, prefs?: UserPreferences): Promise<Article[]> {
  const { level, topics } = config;
    const topicsStr = topics.includes('Random/Surprise Me') 
    ? "foundational Product Design concepts"
    : topics.join(", ");

  const preferenceContext = getPreferenceContext(prefs);

  const prompt = `
    ACT AS: A Lead Product Designer and Editor.
    TASK: Curate a reading list of 4 foundational/seminal design articles from your internal knowledge base.
    TARGET AUDIENCE LEVEL: ${level}.
    TOPICS: ${topicsStr}.

    ${preferenceContext}

    Since you cannot browse the live web right now, generate REAL, well-known articles that exist in your training data (e.g., from NNGroup, Baymard, famous Medium posts). Do not hallucinate fake URLs if possible, or use standard domain homepages if specific URL is unknown.

    OUTPUT FORMAT: Return a JSON array of 4 Article objects.
    CRITICAL: In the 'application_tips' section, explain exactly 'How I can apply these learnings myself'.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: digestSchema,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No text returned from KB generation");

    const parsed = JSON.parse(cleanJsonString(text));
    return parsed as Article[];
  } catch (error) {
    console.warn("Attempt 2 (KB) failed:", error);
    throw error;
  }
}

/**
 * Main function to fetch digest with fallback chain
 */
export async function fetchLiveDigest(config: DigestConfig, prefs?: UserPreferences): Promise<Article[]> {
  // Attempt 1: Search
  try {
    const articles = await generateWithSearch(config, prefs);
    if (articles && articles.length > 0) return articles;
  } catch (e) { /* continue */ }

  // Attempt 2: Knowledge Base
  try {
    const articles = await generateFromKnowledgeBase(config, prefs);
    if (articles && articles.length > 0) return articles;
  } catch (e) { /* continue */ }

  // Attempt 3: Hardcoded Fallback
  console.warn("All AI attempts failed. Using fallback data.");
  // Randomly select 4 from fallback if we had more, but for now return all 4
  return FALLBACK_ARTICLES;
}

/**
 * URL Analyzer Service
 */
export async function analyzeUrl(url: string): Promise<Article> {
  const prompt = `
    ACT AS: A Lead Product Designer.
    TASK: Analyze the following content URL. Read it and generate a detailed summary card.
    URL: ${url}

    OUTPUT FORMAT: Return a SINGLE JSON Article object.

    Structure:
    {
      "id": "uuid",
      "title": "Title",
      "author": "Author",
      "source": "Source",
      "type": "Article" | "Video",
      "category": "Main Category",
      "url": "${url}",
      "summary": ["para1", "para2", "para3"],
      "insights": ["insight1", "insight2", "insight3", "insight4", "insight5"],
      "application_tips": ["tip1", "tip2", "tip3", "tip4", "tip5"]
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: articleSchema,
      },
    });

    const text = response.text;
    if (!text) throw new Error("No analysis returned");

    const parsed = JSON.parse(cleanJsonString(text));
    return parsed as Article;
  } catch (error) {
    console.error("URL Analysis failed:", error);
    // Return a mock error article so the UI doesn't crash
    return {
      id: 'error_' + Date.now(),
      title: 'Analysis Failed',
      author: 'System',
      source: 'Internal',
      type: 'Article',
      category: 'Error',
      url: url,
      summary: ['We could not analyze this URL at the moment.', 'Please try again later or check the URL.', 'The AI service may be temporarily unavailable.'],
      insights: ['N/A'],
      application_tips: ['Try a different URL', 'Check your internet connection']
    };
  }
}

