import { GoogleGenAI, Type } from "@google/genai";
import { Article, DigestConfig, ExperienceLevel, Topic, UserPreferences } from "../types";
import { FALLBACK_ARTICLES } from "../constants";

// Using Gemini 3 Pro for superior reasoning and tool use adherence to prevent broken links
const MODEL_NAME = 'gemini-3-pro-preview';

/**
 * Helper to get the AI instance with the user's stored key
 */
const getAiInstance = (): GoogleGenAI => {
  const apiKey = localStorage.getItem('ddd_api_key');
  if (!apiKey) {
    throw new Error("API Key not found. Please enter your key.");
  }
  return new GoogleGenAI({ apiKey });
};

// 2. Define Response Schema
// We define the schema for a single article and a list of articles to ensure strict JSON output.
// NOTE: We only use this for Knowledge Base generation. For Search, we use prompt engineering to avoid conflicts.
const articleSchema = {
  type: Type.OBJECT,
  properties: {
    id: { type: Type.STRING },
    title: { type: Type.STRING },
    author: { type: Type.STRING },
    source: { type: Type.STRING },
    type: { type: Type.STRING, enum: ["Article", "Video"] },
    category: { type: Type.STRING },
    url: { type: Type.STRING },
    summary: { type: Type.ARRAY, items: { type: Type.STRING } },
    insights: { type: Type.ARRAY, items: { type: Type.STRING } },
    application_tips: { type: Type.ARRAY, items: { type: Type.STRING } }
  },
  required: ["id", "title", "author", "source", "type", "category", "url", "summary", "insights", "application_tips"]
};

const digestSchema = {
  type: Type.ARRAY,
  items: articleSchema
};

/**
 * Helper to clean JSON string if the model returns markdown code blocks or conversational text
 */
const cleanJsonString = (str: string): string => {
  let cleaned = str.trim();

  // Try to extract JSON from code blocks first
  const codeBlockRegex = /```json\s*([\s\S]*?)\s*```/;
  const match = cleaned.match(codeBlockRegex);
  if (match) {
    cleaned = match[1];
  } else {
    // If no code blocks, try to find the first [ or { and the last ] or }
    const firstBrace = cleaned.indexOf('{');
    const firstBracket = cleaned.indexOf('[');

    let startIndex = -1;
    let endIndex = -1;

    // Determine if we are looking for an object or array
    if (firstBracket !== -1 && (firstBrace === -1 || firstBracket < firstBrace)) {
        startIndex = firstBracket;
        endIndex = cleaned.lastIndexOf(']');
    } else if (firstBrace !== -1) {
        startIndex = firstBrace;
        endIndex = cleaned.lastIndexOf('}');
    }

    if (startIndex !== -1 && endIndex !== -1) {
        cleaned = cleaned.substring(startIndex, endIndex + 1);
    }
  }

  return cleaned;
};

/**
 * Helper to construct preference string
 */
const getPreferenceContext = (prefs?: UserPreferences): string => {
  if (!prefs) return "";

  let context = "";
  if (prefs.likedArticles.length > 0) {
    const likedTitles = prefs.likedArticles.slice(0, 5).map(a => `"${a.title}" (${a.category})`).join(", ");
    context += `USER FEEDBACK - POSITIVE: The user previously found these articles helpful: ${likedTitles}. Prioritize similar topics, sources, or depth.\n`;
  }

  if (prefs.dislikedArticles.length > 0) {
    const dislikedTitles = prefs.dislikedArticles.slice(0, 5).map(a => `"${a.title}"`).join(", ");
    context += `USER FEEDBACK - NEGATIVE: The user disliked these articles: ${dislikedTitles}. Avoid similar content.\n`;
  }

  return context;
};

/**
 * Attempt 1: Search-Enabled Generation
 */
async function generateWithSearch(config: DigestConfig, prefs?: UserPreferences): Promise<Article[]> {
  const ai = getAiInstance();
  const { level, topics, dateRange } = config;

  let topicsStr = topics.includes('Random/Surprise Me') 
    ? "trending Product Design, UX Strategy, and UI Engineering topics"
    : topics.join(", ");

  // Explicitly prompt for redesigns if case studies are requested
  if (topics.some(t => t.includes('Case Studies'))) {
    topicsStr += ". Include detailed Product/UX Redesign case studies if available";
  }

  const preferenceContext = getPreferenceContext(prefs);

  const prompt = `
    ACT AS: A Lead Product Designer.
    TASK: Find 4 unique, high-quality articles or videos relevant to the topics.
    DATE CONSTRAINT: The articles MUST be published within: ${dateRange}.
    TARGET AUDIENCE LEVEL: ${level}.
    TOPICS: ${topicsStr}.
    PREFERRED SOURCES: Reputable design publications like UX Collective, NNGroup, Smashing Magazine, A List Apart, The Futur, Growth.design, Reforge, Linear Blog, Figma Blog, or similar high-quality industry voices.

    ${preferenceContext}

    OUTPUT FORMAT: 
    Return a RAW JSON array of 4 Article objects. 
    Do NOT include any conversational text outside the JSON.
    Ensure the JSON is valid and follows this schema exactly:

    [
      {
        "id": "uuid",
        "title": "Title",
        "author": "Author",
        "source": "Source Name",
        "type": "Article" | "Video",
        "category": "Topic Category",
        "url": "THE_EXACT_SOURCE_URL_FOUND_BY_SEARCH",
        "summary": ["para1", "para2", "para3"],
        "insights": ["insight1", "insight2", "insight3", "insight4", "insight5", "insight6"],
        "application_tips": ["tip1", "tip2", "tip3", "tip4", "tip5", "tip6"]
      }
    ]

    CRITICAL RULES FOR URL ACCURACY:
    1. You MUST use the Google Search tool to find these articles.
    2. The 'url' field MUST be the EXACT, FUNCTIONAL URL returned by the Google Search tool grounding.
    3. DO NOT fabricate, hallucinate, or guess URLs. Do NOT construct URLs (e.g. 'medium.com/author/title').
    4. If the search result does not explicitly provide a direct link to the article, DISCARD that item.
    5. Do NOT use search result pages (google.com/search?...) or truncated URLs.
    6. Quality over quantity: If you can only find 2 or 3 articles with VERIFIED URLs, return only those.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        // We do NOT use responseSchema here because it conflicts with Search grounding in some cases
      },
    });

    const text = response.text;
    if (!text) throw new Error("No text returned from Search generation");

    const parsed = JSON.parse(cleanJsonString(text));
    return parsed as Article[];
  } catch (error) {
    console.warn("Attempt 1 (Search) failed:", error);
    throw error;
  }
}

/**
 * Attempt 2: Fallback Broad Search
 * If strict date/topic search fails, we try a broader search for timeless/popular content
 * We still use Search to ensure links are valid.
 */
async function generateBroadSearch(config: DigestConfig, prefs?: UserPreferences): Promise<Article[]> {
  const ai = getAiInstance();
  const { level, topics } = config;

  let topicsStr = topics.includes('Random/Surprise Me') 
    ? "foundational Product Design concepts"
    : topics.join(", ");

  if (topics.some(t => t.includes('Case Studies'))) {
    topicsStr += " (including famous redesign case studies)";
  }

  const preferenceContext = getPreferenceContext(prefs);

  const prompt = `
    ACT AS: A Lead Product Designer and Editor.
    TASK: Find 4 classic, seminal, or highly popular design articles/videos that are timeless.
    TARGET AUDIENCE LEVEL: ${level}.
    TOPICS: ${topicsStr}.

    ${preferenceContext}

    INSTRUCTIONS:
    1. Use Google Search to find reputable articles from sources like NNGroup, Baymard, Smashing Magazine, or A List Apart.
    2. Ensure the URLs are valid and functional.

    OUTPUT FORMAT: Return a JSON array of 4 Article objects.

    [
      {
        "id": "uuid",
        "title": "Title",
        "author": "Author",
        "source": "Source Name",
        "type": "Article" | "Video",
        "category": "Topic Category",
        "url": "THE_EXACT_URL",
        "summary": ["para1"],
        "insights": ["insight1"],
        "application_tips": ["tip1"]
      }
    ]

    CRITICAL: 
    - The 'url' must be extracted directly from the search tool.
    - Do not guess links. 
    - Do not output broken links.
    - If a link cannot be verified by the search tool, do not include the article.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }], // Enable search here too to fix broken links issue
      },
    });

    const text = response.text;
    if (!text) throw new Error("No text returned from Broad Search generation");

    const parsed = JSON.parse(cleanJsonString(text));
    return parsed as Article[];
  } catch (error) {
    console.warn("Attempt 2 (Broad Search) failed:", error);
    throw error;
  }
}

/**
 * Main function to fetch digest with fallback chain
 */
export async function fetchLiveDigest(config: DigestConfig, prefs?: UserPreferences): Promise<Article[]> {
  try {
    // Attempt 1: Search (Strict Constraints)
    try {
      const articles = await generateWithSearch(config, prefs);
      if (articles && articles.length > 0) return articles;
    } catch (e) { 
      console.log("Primary search failed, trying broad search...", e);
    }

    // Attempt 2: Broad Search (Relaxed Constraints, but still verifying links)
    try {
      const articles = await generateBroadSearch(config, prefs);
      if (articles && articles.length > 0) return articles;
    } catch (e) {
      console.log("Broad search failed, using hardcoded fallback.", e);
    }

    // Attempt 3: Hardcoded Fallback
    console.warn("All AI attempts failed. Using fallback data.");
    return FALLBACK_ARTICLES;
  } catch (finalError) {
      console.error("Critical failure in service:", finalError);
      throw finalError; // Rethrow so UI can handle (or show Key error)
  }
}

/**
 * URL Analyzer Service - Two-Step Robustness
 */
export async function analyzeUrl(url: string): Promise<Article> {
  const ai = getAiInstance();
  const commonInstructions = `
    OUTPUT FORMAT: 
    Return a SINGLE RAW JSON Article object.
    Do NOT include any conversational text.

    Structure:
    {
      "id": "uuid",
      "title": "Title",
      "author": "Author",
      "source": "Source",
      "type": "Article" | "Video",
      "category": "Main Category",
      "url": "${url}",
      "summary": ["para1", "para2", "para3"],
      "insights": ["insight1", "insight2", "insight3", "insight4", "insight5", "insight6"],
      "application_tips": ["tip1", "tip2", "tip3", "tip4", "tip5", "tip6"]
    }

    CRITICAL: In the 'insights' and 'application_tips' sections, provide COMPREHENSIVE lists. Do NOT limit to 3 items. Aim for 5-7 distinct, valuable points.
  `;

  // STEP 1: Try with Search
  try {
    const prompt = `
      ACT AS: A Lead Product Designer.
      TASK: Analyze the content at this URL: ${url}

      INSTRUCTIONS:
      1. Use the Google Search tool to find the content of this page. 
      2. If the URL is not directly accessible, search for the title + author to find the content.
      3. Synthesize a detailed summary and analysis.

      ${commonInstructions}
    `;

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        // No schema here to allow tool use flexibility
      },
    });

    const text = response.text;
    if (!text) throw new Error("No analysis returned");

    const parsed = JSON.parse(cleanJsonString(text));
    parsed.url = url; 
    return parsed as Article;

  } catch (searchError) {
    console.warn("URL Analysis (Search) failed, retrying with Inference...", searchError);

    // STEP 2: Retry without Search (Inference/Knowledge Base)
    // This prevents the "Analysis Failed" screen by falling back to what the model knows or can infer.
    try {
      const prompt = `
        ACT AS: A Lead Product Designer.
        TASK: Analyze this URL: ${url}

        It seems the live search for this URL failed. 
        Please infer the likely content based on the URL structure, keywords, or your internal knowledge base if it's a famous article.

        If you really cannot guess the specific content, provide a "Best Practices" guide for the TOPIC referenced in the URL string.
        Mark the source as "AI Inference".

        ${commonInstructions}
      `;

      const response = await ai.models.generateContent({
        model: MODEL_NAME,
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: articleSchema, // We can use strict schema here since no tools are used
        },
      });

      const text = response.text;
      if (!text) throw new Error("No fallback analysis returned");

      const parsed = JSON.parse(cleanJsonString(text));
      parsed.url = url;
      return parsed as Article;

    } catch (fallbackError) {
      console.error("All URL Analysis attempts failed:", fallbackError);

      // Final Fallback to prevent crash
      return {
        id: 'error_' + Date.now(),
        title: 'Analysis Unavailable',
        author: 'System',
        source: 'Internal',
        type: 'Article',
        category: 'Error',
        url: url,
        summary: ['We could not analyze this URL at the moment.', 'Please try again later or check the URL.'],
        insights: ['N/A'],
        application_tips: ['Try a different URL', 'Check your internet connection']
      };
    }
  }
}

import React, { useState, useEffect } from 'react';
import { DigestConfig, Article, DigestHistoryItem, UserPreferences } from './types';
import { fetchLiveDigest, analyzeUrl } from './services/geminiService';
import DigestConfigurator from './components/DigestConfigurator';
import ArticleCard from './components/ArticleCard';
import UrlAnalyzer from './components/UrlAnalyzer';
import SkeletonLoader from './components/SkeletonLoader';
import ApiKeyInput from './components/ApiKeyInput';
import { Newspaper, History, Clock, ArrowLeft, Bookmark, Quote, Home, Shuffle, Key, LogOut } from 'lucide-react';
import { DESIGN_QUOTES } from './constants';

// ID Generator Helper (Polyfill for crypto.randomUUID in insecure contexts)
const generateId = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return Date.now().toString(36) + Math.random().toString(36).substring(2);
};

// Main App Component
function App() {
  // State
  const [hasApiKey, setHasApiKey] = useState(false);
  const [view, setView] = useState<'dashboard' | 'history' | 'result' | 'saved'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [loadingMode, setLoadingMode] = useState<'feed' | 'url'>('feed'); // Track loading context
  const [articles, setArticles] = useState<Article[]>([]);
  const [history, setHistory] = useState<DigestHistoryItem[]>([]);

  // Interaction State
  const [savedArticles, setSavedArticles] = useState<Article[]>([]);
  const [likedArticles, setLikedArticles] = useState<Article[]>([]);
  const [dislikedArticles, setDislikedArticles] = useState<Article[]>([]);

  // Configuration State
  const [config, setConfig] = useState<DigestConfig>({
    level: 'Mid-Level',
    topics: ['Random/Surprise Me'],
    dateRange: 'Last Month'
  });

  // Daily Quote State
  const [currentQuote, setCurrentQuote] = useState(DESIGN_QUOTES[0]);

  // Check for API Key on mount
  useEffect(() => {
    const key = localStorage.getItem('ddd_api_key');
    if (key) {
      setHasApiKey(true);
    }
  }, []);

  // Initialize random quote on mount
  useEffect(() => {
    setCurrentQuote(DESIGN_QUOTES[Math.floor(Math.random() * DESIGN_QUOTES.length)]);
  }, []);

  const handleSaveApiKey = (key: string) => {
    localStorage.setItem('ddd_api_key', key);
    setHasApiKey(true);
  };

  const handleResetApiKey = () => {
    try {
      localStorage.removeItem('ddd_api_key');
    } catch (e) {
      console.error("Error removing key from storage", e);
    }
    setHasApiKey(false);
    setView('dashboard');
    setArticles([]); 
  };

  const handleNewQuote = () => {
    let newIndex;
    do {
      newIndex = Math.floor(Math.random() * DESIGN_QUOTES.length);
    } while (DESIGN_QUOTES[newIndex].text === currentQuote.text && DESIGN_QUOTES.length > 1);

    setCurrentQuote(DESIGN_QUOTES[newIndex]);
  };

  // Load persistence
  useEffect(() => {
    const loadState = () => {
      try {
        const h = localStorage.getItem('ddd_history');
        if (h) setHistory(JSON.parse(h));

        const s = localStorage.getItem('ddd_saved');
        if (s) setSavedArticles(JSON.parse(s));

        const l = localStorage.getItem('ddd_liked');
        if (l) setLikedArticles(JSON.parse(l));

        const d = localStorage.getItem('ddd_disliked');
        if (d) setDislikedArticles(JSON.parse(d));
      } catch (e) {
        console.error("Failed to parse local storage", e);
      }
    };
    loadState();
  }, []);

  // Save persistence with error handling
  useEffect(() => {
    try {
      localStorage.setItem('ddd_history', JSON.stringify(history));
    } catch (e) {
      console.error("Failed to save history to local storage", e);
    }
  }, [history]);

  useEffect(() => {
    try {
      localStorage.setItem('ddd_saved', JSON.stringify(savedArticles));
    } catch (e) {
      console.error("Failed to save saved articles to local storage", e);
    }
  }, [savedArticles]);

  useEffect(() => {
    try {
      localStorage.setItem('ddd_liked', JSON.stringify(likedArticles));
    } catch (e) {
      console.error("Failed to save liked articles", e);
    }
  }, [likedArticles]);

  useEffect(() => {
    try {
      localStorage.setItem('ddd_disliked', JSON.stringify(dislikedArticles));
    } catch (e) {
      console.error("Failed to save disliked articles", e);
    }
  }, [dislikedArticles]);

  // Handlers
  const handleGenerateDigest = async () => {
    setLoading(true);
    setLoadingMode('feed');
    setView('result');
    setArticles([]); // Clear previous

    try {
      const prefs: UserPreferences = {
        likedArticles,
        dislikedArticles
      };

      const results = await fetchLiveDigest(config, prefs);
      setArticles(results);

      // Save to history
      const historyItem: DigestHistoryItem = {
        id: generateId(),
        timestamp: Date.now(),
        config: config,
        articles: results,
        type: 'feed'
      };
      setHistory(prev => [historyItem, ...prev]);
    } catch (err) {
      console.error("Failed to generate digest", err);
      if (err instanceof Error && err.message.includes("API Key")) {
         alert("API Key missing or invalid. Please re-enter.");
         setHasApiKey(false);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleAnalyzeUrl = async (url: string) => {
    setLoading(true);
    setLoadingMode('url');
    setView('result');
    setArticles([]);

    try {
      const result = await analyzeUrl(url);
      setArticles([result]);

      const historyItem: DigestHistoryItem = {
        id: generateId(),
        timestamp: Date.now(),
        config: { level: config.level, topics: [], dateRange: 'Any Time' }, // Empty topics for URL
        articles: [result],
        type: 'url'
      };
      setHistory(prev => [historyItem, ...prev]);
    } catch (err) {
      console.error("Failed to analyze URL", err);
      if (err instanceof Error && err.message.includes("API Key")) {
        alert("API Key missing or invalid. Please re-enter.");
        setHasApiKey(false);
     }
    } finally {
      setLoading(false);
    }
  };

  const restoreHistoryItem = (item: DigestHistoryItem) => {
    setArticles(item.articles);
    setView('result');
  };

  // Interaction Handlers
  const handleToggleSave = (article: Article) => {
    setSavedArticles(prev => {
      const exists = prev.some(a => a.url === article.url);
      if (exists) {
        return prev.filter(a => a.url !== article.url);
      } else {
        return [article, ...prev];
      }
    });
  };

  const handleRate = (article: Article, rating: 'up' | 'down' | null) => {
    const cleanLiked = likedArticles.filter(a => a.url !== article.url);
    const cleanDisliked = dislikedArticles.filter(a => a.url !== article.url);

    setLikedArticles(cleanLiked);
    setDislikedArticles(cleanDisliked);

    if (rating === 'up') {
      setLikedArticles([article, ...cleanLiked]);
    } else if (rating === 'down') {
      setDislikedArticles([article, ...cleanDisliked]);
    }
  };

  const getArticleRating = (article: Article): 'up' | 'down' | null => {
    if (likedArticles.some(a => a.url === article.url)) return 'up';
    if (dislikedArticles.some(a => a.url === article.url)) return 'down';
    return null;
  };

  const isArticleSaved = (article: Article): boolean => {
    return savedArticles.some(a => a.url === article.url);
  };

  // Render Helpers
  const renderFloatingControls = () => (
    <div className="fixed top-6 right-6 z-50 flex flex-col items-end gap-4 pointer-events-none">
      <div className="flex gap-2 pointer-events-auto bg-white/90 backdrop-blur-md p-1.5 rounded-full shadow-lg border border-stone-200/50 hover:shadow-xl transition-all duration-300">
        <button
            onClick={() => setView('dashboard')}
            className={`p-3 rounded-full transition-all duration-200 active:scale-90 ${view === 'dashboard' ? 'text-charcoal bg-stone-50' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-50'}`}
            title="Home"
        >
             <Home className="w-5 h-5" />
        </button>
        <div className="w-px h-6 bg-stone-200 my-auto"></div>
        <button 
          onClick={() => setView(view === 'saved' ? 'dashboard' : 'saved')}
          className={`relative p-3 rounded-full transition-all duration-200 active:scale-90 ${view === 'saved' ? 'text-amber-600 bg-amber-50' : 'text-stone-500 hover:text-stone-700 hover:bg-stone-50'}`}
          title="Read Later"
        >
          <Bookmark className={`w-5 h-5 ${view === 'saved' ? 'fill-current' : ''}`} />
          {savedArticles.length > 0 && (
            <span className="absolute top-2 right-2 w-2 h-2 bg-amber-500 rounded-full border border-white"></span>
          )}
        </button>

        <button 
          onClick={() => setView(view === 'history' ? 'dashboard' : 'history')}
          className={`p-3 rounded-full transition-all duration-200 active:scale-90 ${view === 'history' ? 'text-charcoal bg-stone-100' : 'text-stone-500 hover:text-stone-700 hover:bg-stone-50'}`}
          title="History"
        >
          <History className="w-5 h-5" />
        </button>

        <div className="w-px h-6 bg-stone-200 my-auto"></div>

        <button 
          onClick={handleResetApiKey}
          className="p-3 rounded-full transition-all duration-200 hover:bg-red-50 hover:text-red-600 text-stone-400 active:scale-90 group"
          title="Sign Out / Reset Key"
        >
          <LogOut className="w-5 h-5 group-hover:translate-x-0.5 transition-transform" />
        </button>
      </div>
    </div>
  );

  const renderDashboard = () => (
    <div className="space-y-16 animate-in fade-in duration-700 pt-32">
      {/* Hero Title */}
      <section className="text-center space-y-4">
        <h1 className="font-serif text-5xl md:text-7xl text-charcoal tracking-tight">
          Daily Design Digest
        </h1>
        <p className="text-stone-500 text-lg md:text-xl font-serif italic max-w-xl mx-auto">
          Curated intelligence for product designers, strategists, and engineers.
        </p>
      </section>

      <section>
        <DigestConfigurator 
          config={config} 
          setConfig={setConfig} 
          onGenerate={handleGenerateDigest} 
          isLoading={loading}
        />
      </section>

      <section className="border-t border-stone-200 border-dashed pt-16">
        <UrlAnalyzer onAnalyze={handleAnalyzeUrl} isLoading={loading} />
      </section>
    </div>
  );

  const renderArticleList = (list: Article[], emptyMessage: string) => (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pb-20">
      {list.length === 0 ? (
         <div className="col-span-full text-center py-20 bg-white rounded-2xl border border-stone-200 border-dashed">
            <Newspaper className="w-12 h-12 text-stone-300 mx-auto mb-4" />
            <p className="text-stone-500 font-medium">{emptyMessage}</p>
         </div>
      ) : (
        list.map((article) => (
          <ArticleCard 
            key={article.url}
            article={article} 
            isSaved={isArticleSaved(article)}
            rating={getArticleRating(article)}
            onToggleSave={handleToggleSave}
            onRate={handleRate}
          />
        ))
      )}
    </div>
  );

  const renderResults = () => (
    <div className="animate-in slide-in-from-bottom-4 duration-500 pt-24">
      <div className="mb-8 flex items-center justify-between">
        <button 
          onClick={() => setView('dashboard')}
          className="flex items-center text-stone-500 hover:text-stone-900 transition-all duration-200 font-medium group bg-white/50 px-4 py-2 rounded-full hover:bg-white border border-transparent hover:border-stone-200 active:scale-95"
        >
          <ArrowLeft className="w-4 h-4 mr-2 group-hover:-translate-x-1 transition-transform" />
          Dashboard
        </button>
        <span className="text-stone-400 text-sm font-serif italic">
          {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}
        </span>
      </div>

      {loading ? (
        <SkeletonLoader mode={loadingMode} />
      ) : (
        renderArticleList(articles, "No articles generated.")
      )}
    </div>
  );

  const renderSaved = () => (
    <div className="animate-in fade-in duration-300 pt-24">
       <div className="mb-8">
        <button 
          onClick={() => setView('dashboard')}
          className="flex items-center text-stone-500 hover:text-stone-900 transition-all duration-200 font-medium group mb-6 bg-white/50 px-4 py-2 rounded-full hover:bg-white border border-transparent hover:border-stone-200 w-fit active:scale-95"
        >
          <ArrowLeft className="w-4 h-4 mr-2 group-hover:-translate-x-1 transition-transform" />
          Dashboard
        </button>
        <h2 className="font-serif text-4xl mb-2 text-charcoal">Reading List</h2>
        <p className="text-stone-500">Your personal library of saved insights.</p>
      </div>
      {renderArticleList(savedArticles, "Your reading list is empty.")}
    </div>
  );

  const renderHistory = () => (
    <div className="max-w-3xl mx-auto pb-20 animate-in fade-in duration-300 pt-24">
      <div className="mb-8">
        <button 
          onClick={() => setView('dashboard')}
          className="flex items-center text-stone-500 hover:text-stone-900 transition-all duration-200 font-medium group mb-6 bg-white/50 px-4 py-2 rounded-full hover:bg-white border border-transparent hover:border-stone-200 w-fit active:scale-95"
        >
          <ArrowLeft className="w-4 h-4 mr-2 group-hover:-translate-x-1 transition-transform" />
          Dashboard
        </button>
        <h2 className="font-serif text-4xl mb-2 text-charcoal">Archive</h2>
        <p className="text-stone-500">Previous briefings.</p>
      </div>

      {history.length === 0 ? (
        <div className="text-center py-20 bg-white rounded-2xl border border-stone-200 border-dashed">
          <Newspaper className="w-12 h-12 text-stone-300 mx-auto mb-4" />
          <p className="text-stone-500">No digests generated yet.</p>
        </div>
      ) : (
        <div className="space-y-4">
          {history.map((item) => (
            <div 
              key={item.id}
              onClick={() => restoreHistoryItem(item)}
              className="bg-white p-6 rounded-xl border border-stone-200 hover:border-stone-400 hover:shadow-md cursor-pointer transition-all duration-300 flex justify-between items-center group active:scale-[0.99]"
            >
              <div>
                <div className="flex items-center text-xs text-stone-400 mb-2 uppercase tracking-wider">
                  <Clock className="w-3 h-3 mr-1" />
                  {new Date(item.timestamp).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' })}
                  {item.type === 'url' && <span className="ml-2 bg-stone-100 text-stone-600 px-2 rounded-full">URL</span>}
                </div>
                <h3 className="font-serif text-lg text-stone-800 group-hover:text-charcoal font-medium">
                  {item.type === 'url' 
                    ? item.articles[0]?.title || 'Analyzed URL' 
                    : `${item.articles.length} Articles • ${item.config.level}`}
                </h3>
                {item.type === 'feed' && (
                  <div className="flex flex-wrap gap-2 mt-2">
                     <span className="text-xs bg-amber-50 px-2 py-1 rounded-md text-amber-700 font-medium">
                        {item.config.dateRange}
                     </span>
                    {item.config.topics.slice(0, 3).map(t => (
                      <span key={t} className="text-xs bg-stone-50 px-2 py-1 rounded-md text-stone-500">
                        {t}
                      </span>
                    ))}
                  </div>
                )}
              </div>
              <ArrowLeft className="rotate-180 text-stone-300 group-hover:text-stone-900 transition-colors group-hover:translate-x-1" />
            </div>
          ))}
        </div>
      )}
    </div>
  );

  const renderFooter = () => (
    <footer className="mt-24 pb-12 text-center text-stone-400 px-4 group/footer">
      <div className="max-w-2xl mx-auto border-t border-stone-200 pt-8 relative">
        <div className="flex items-center justify-center gap-2 mb-4">
            <Quote className="w-6 h-6 opacity-50 text-stone-300" />
            <button 
                onClick={handleNewQuote}
                className="p-2 rounded-full text-stone-300 hover:text-stone-500 hover:bg-stone-100 opacity-0 group-hover/footer:opacity-100 transition-all duration-300 active:rotate-180"
                title="Shuffle Quote"
            >
                <Shuffle className="w-4 h-4" />
            </button>
        </div>
        <div className="min-h-[6rem] flex flex-col justify-center animate-in fade-in duration-500 key={currentQuote.text}">
            <p className="font-serif text-lg md:text-xl text-stone-600 mb-2 italic">
            "{currentQuote.text}"
            </p>
            <p className="text-sm font-medium uppercase tracking-widest text-stone-400">
            — {currentQuote.author}
            </p>
        </div>
      </div>
    </footer>
  );

  // Initial State: No API Key
  if (!hasApiKey) {
    return (
        <div className="min-h-screen font-sans text-charcoal bg-stone-50">
            <ApiKeyInput onSave={handleSaveApiKey} />
        </div>
    );
  }

  return (
    <div className="min-h-screen font-sans text-charcoal selection:bg-stone-200 selection:text-black flex flex-col">
      {renderFloatingControls()}

      <main className="max-w-6xl mx-auto px-4 flex-grow w-full">
        {view === 'dashboard' && renderDashboard()}
        {view === 'result' && renderResults()}
        {view === 'history' && renderHistory()}
        {view === 'saved' && renderSaved()}
      </main>

      {renderFooter()}
    </div>
  );
}

export default App;

import React from 'react';
import { DigestConfig, ExperienceLevel, Topic, DateRange } from '../types';
import { AVAILABLE_TOPICS } from '../constants';
import { RefreshCw, Check, Clock } from 'lucide-react';

interface DigestConfiguratorProps {
  config: DigestConfig;
  setConfig: React.Dispatch<React.SetStateAction<DigestConfig>>;
  onGenerate: () => void;
  isLoading: boolean;
}

const DigestConfigurator: React.FC<DigestConfiguratorProps> = ({ config, setConfig, onGenerate, isLoading }) => {

  const toggleTopic = (topic: Topic) => {
    setConfig(prev => {
      // If selecting Random, clear others. If selecting others, clear Random.
      if (topic === 'Random/Surprise Me') {
        return { ...prev, topics: ['Random/Surprise Me'] };
      }

      const newTopics = prev.topics.filter(t => t !== 'Random/Surprise Me');
      if (prev.topics.includes(topic)) {
        return { ...prev, topics: newTopics.filter(t => t !== topic) };
      } else {
        return { ...prev, topics: [...newTopics, topic] };
      }
    });
  };

  const handleLevelChange = (level: ExperienceLevel) => {
    setConfig(prev => ({ ...prev, level }));
  };

  const handleDateRangeChange = (dateRange: DateRange) => {
    setConfig(prev => ({ ...prev, dateRange }));
  };

  const dateRanges: DateRange[] = ['Last 24 Hours', 'Last Week', 'Last Month', 'Last 6 Months', 'Any Time'];

  const levels: { id: ExperienceLevel; title: string; subtitle: string }[] = [
    { id: 'Junior', title: 'Foundations', subtitle: 'Core Concepts' },
    { id: 'Mid-Level', title: 'Deep Dive', subtitle: 'Detailed Analysis' },
    { id: 'Senior', title: 'Strategic', subtitle: 'Leadership & Systems' },
  ];

  return (
    <div className="bg-white rounded-2xl p-6 md:p-8 shadow-sm max-w-4xl mx-auto mb-12 relative overflow-hidden group">
      <div className="relative z-10 flex flex-col md:flex-row gap-8 md:gap-12">

        {/* Left Column: Level & Time */}
        <div className="flex-shrink-0 md:w-1/3 space-y-8">

          {/* Experience Level */}
          <div className="space-y-4">
            {levels.map((lvl) => {
              const isSelected = config.level === lvl.id;
              return (
                <button
                  key={lvl.id}
                  onClick={() => handleLevelChange(lvl.id)}
                  className={`
                    w-full relative px-4 py-3 text-left rounded-xl text-sm font-medium transition-all duration-200 ease-out border active:scale-[0.98]
                    ${isSelected 
                      ? 'bg-stone-900 border-stone-900 text-white shadow-lg shadow-stone-200 transform scale-[1.02] ring-2 ring-offset-2 ring-stone-900' 
                      : 'bg-white border-stone-200 text-stone-600 hover:border-stone-300 hover:bg-stone-50 hover:shadow-sm'
                    }
                  `}
                >
                  <div className="flex justify-between items-center">
                    <span className="font-serif text-base tracking-tight block mb-0.5">
                      {lvl.title}
                    </span>
                    {isSelected && <Check className="w-4 h-4 text-amber-200" />}
                  </div>
                  <span className={`text-[10px] uppercase tracking-wide opacity-80 ${isSelected ? 'text-stone-300' : 'text-stone-400'}`}>
                    {lvl.subtitle}
                  </span>
                </button>
              );
            })}
          </div>

          {/* Timeframe */}
          <div>
            <div className="flex items-center text-xs font-bold uppercase tracking-widest text-stone-400 mb-3 pl-1">
              <Clock className="w-3 h-3 mr-1.5" />
              Timeframe
            </div>
            <div className="flex flex-wrap gap-2">
              {dateRanges.map((range) => {
                const isSelected = config.dateRange === range;
                return (
                  <button
                    key={range}
                    onClick={() => handleDateRangeChange(range)}
                    className={`
                      px-3 py-1.5 rounded-lg text-xs font-medium border transition-all duration-200 active:scale-95
                      ${isSelected
                        ? 'bg-stone-100 border-stone-300 text-stone-900 font-semibold ring-1 ring-stone-300'
                        : 'bg-white border-stone-100 text-stone-400 hover:border-stone-200 hover:text-stone-600'
                      }
                    `}
                  >
                    {range}
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        {/* Right Column: Topics */}
        <div className="flex-grow space-y-4 border-l border-stone-100 pl-0 md:pl-10">
           <div className="flex items-center text-xs font-bold uppercase tracking-widest text-stone-400 mb-1 pl-1 md:hidden">
              Topics
            </div>
          <div className="flex flex-wrap gap-2.5">
            {AVAILABLE_TOPICS.map((topic) => {
              const isSelected = config.topics.includes(topic);
              return (
                <button
                  key={topic}
                  onClick={() => toggleTopic(topic)}
                  className={`
                    px-4 py-2.5 rounded-lg text-sm font-medium border transition-all duration-200 active:scale-95
                    ${isSelected
                      ? 'bg-stone-800 border-stone-800 text-white shadow-md ring-2 ring-offset-1 ring-stone-800'
                      : 'bg-white border-stone-200 text-stone-500 hover:border-stone-300 hover:text-stone-700 hover:bg-stone-50'
                    }
                  `}
                >
                  {topic}
                </button>
              );
            })}
          </div>
          <p className="text-xs text-stone-400 italic mt-4 pl-1 border-t border-dashed border-stone-200 pt-4">
            Customize your digest by selecting topics.
          </p>
        </div>
      </div>

      <div className="mt-10 flex justify-end pt-6">
        <button
          onClick={onGenerate}
          disabled={isLoading || config.topics.length === 0}
          className={`
            group relative flex items-center px-8 py-4 rounded-full font-serif font-bold text-lg shadow-xl transition-all duration-300
            ${isLoading 
              ? 'bg-stone-100 text-stone-400 cursor-not-allowed translate-y-0 shadow-none' 
              : 'bg-charcoal text-white hover:bg-black hover:-translate-y-1 hover:shadow-2xl hover:shadow-charcoal/20 active:translate-y-0 active:scale-95'
            }
          `}
        >
          {isLoading ? (
            <span className="flex items-center">
              <RefreshCw className="mr-2 w-5 h-5 animate-spin" />
              Synthesizing...
            </span>
          ) : (
            <>
              <span className="relative z-10">Generate Briefing</span>
              <RefreshCw className="ml-3 w-5 h-5 transition-transform group-hover:rotate-180" />
            </>
          )}
        </button>
      </div>
    </div>
  );
};

export default DigestConfigurator;

import React from 'react';
import { ExternalLink, Lightbulb, Zap, BookOpen, PlayCircle, Bookmark, ThumbsUp, ThumbsDown } from 'lucide-react';
import { Article } from '../types';

interface ArticleCardProps {
  article: Article;
  isSaved?: boolean;
  rating?: 'up' | 'down' | null;
  onToggleSave?: (article: Article) => void;
