        articles: [result],
        type: 'url'
      };
      setHistory(prev => [historyItem, ...prev]);
    } catch (err) {
      console.error("Failed to analyze URL", err);
      alert("Failed to analyze URL.");
    } finally {
      setLoading(false);
    }
  };

  const restoreHistoryItem = (item: DigestHistoryItem) => {
    setArticles(item.articles);
    setView('result');
  };

  // Interaction Handlers
  const handleToggleSave = (article: Article) => {
    setSavedArticles(prev => {
      const exists = prev.some(a => a.url === article.url);
      if (exists) {
        return prev.filter(a => a.url !== article.url);
      } else {
        return [article, ...prev];
      }
    });
  };

  const handleRate = (article: Article, rating: 'up' | 'down' | null) => {
    const cleanLiked = likedArticles.filter(a => a.url !== article.url);
    const cleanDisliked = dislikedArticles.filter(a => a.url !== article.url);

    setLikedArticles(cleanLiked);
    setDislikedArticles(cleanDisliked);

    if (rating === 'up') {
      setLikedArticles([article, ...cleanLiked]);
    } else if (rating === 'down') {
      setDislikedArticles([article, ...cleanDisliked]);
    }
  };

  const getArticleRating = (article: Article): 'up' | 'down' | null => {
    if (likedArticles.some(a => a.url === article.url)) return 'up';
    if (dislikedArticles.some(a => a.url === article.url)) return 'down';
    return null;
  };

  const isArticleSaved = (article: Article): boolean => {
    return savedArticles.some(a => a.url === article.url);
  };

  // Render Helpers
  const renderFloatingControls = () => (
    <div className="fixed top-6 right-6 z-50 flex flex-col items-end gap-4 pointer-events-none">
      <div className="flex gap-1 pointer-events-auto bg-white/80 backdrop-blur-xl p-1.5 rounded-full shadow-lg border border-white/50 hover:shadow-xl transition-all duration-300 ring-1 ring-stone-900/5">
        <button
            onClick={() => setView('dashboard')}
            className={`p-3 rounded-full transition-all duration-300 active:scale-95 ${view === 'dashboard' ? 'text-charcoal bg-stone-100' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-50'}`}
            title="Home"
        >
             <Home className="w-5 h-5" />
        </button>

        <button 
          onClick={() => setView(view === 'saved' ? 'dashboard' : 'saved')}
          className={`relative p-3 rounded-full transition-all duration-300 active:scale-95 ${view === 'saved' ? 'text-amber-700 bg-amber-50' : 'text-stone-400 hover:text-amber-600 hover:bg-amber-50/50'}`}
          title="Read Later"
        >
          <Bookmark className={`w-5 h-5 ${view === 'saved' ? 'fill-current' : ''}`} />
          {savedArticles.length > 0 && (
            <span className="absolute top-2 right-2 w-2 h-2 bg-amber-500 rounded-full border border-white shadow-sm"></span>
          )}
        </button>

        <button 
          onClick={() => setView(view === 'history' ? 'dashboard' : 'history')}
          className={`p-3 rounded-full transition-all duration-300 active:scale-95 ${view === 'history' ? 'text-charcoal bg-stone-100' : 'text-stone-400 hover:text-stone-600 hover:bg-stone-50'}`}
          title="History"
        >
          <History className="w-5 h-5" />
        </button>
      </div>
    </div>
  );

  const renderDashboard = () => (
    <div className="space-y-12 animate-in fade-in duration-700 pt-24 md:pt-32">
      {/* Hero Title */}
      <section className="text-center space-y-6">
        <div className="inline-flex items-center justify-center p-2 bg-stone-100 rounded-full mb-2">
            <Sparkles className="w-4 h-4 text-stone-400" />
        </div>
        <h1 className="font-serif text-5xl md:text-7xl lg:text-8xl text-charcoal tracking-tighter leading-[0.9]">
          Daily Design <br/>
          <span className="text-stone-400 italic font-light">Digest</span>
        </h1>
        <p className="text-stone-500 text-lg md:text-xl font-serif italic max-w-lg mx-auto leading-relaxed">
          Curated intelligence for product designers, strategists, and engineers.
        </p>
      </section>

      <section>
        <DigestConfigurator 
          config={config} 
          setConfig={setConfig} 
          onGenerate={handleGenerateDigest} 
          isLoading={loading}
        />
      </section>

      <section className="pt-8 pb-16">
        <UrlAnalyzer onAnalyze={handleAnalyzeUrl} isLoading={loading} />
      </section>
    </div>
  );

  const renderArticleList = (list: Article[], emptyMessage: string) => (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 pb-20">
      {list.length === 0 ? (
         <div className="col-span-full text-center py-32 bg-white/50 rounded-3xl border border-stone-200 border-dashed backdrop-blur-sm">
            <div className="bg-stone-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6">
                <Newspaper className="w-10 h-10 text-stone-300" />
            </div>
            <p className="text-stone-500 font-serif text-lg italic">{emptyMessage}</p>
         </div>
      ) : (
        list.map((article) => (
          <ArticleCard 
            key={article.url}
            article={article} 
            isSaved={isArticleSaved(article)}
            rating={getArticleRating(article)}
            onToggleSave={handleToggleSave}
            onRate={handleRate}
          />
        ))
      )}
    </div>
  );

  const renderResults = () => (
    <div className="animate-in slide-in-from-bottom-4 duration-500 pt-24">
      <div className="mb-10 flex items-center justify-between sticky top-6 z-30 bg-cream/90 backdrop-blur-md p-4 -mx-4 rounded-2xl border border-stone-100 shadow-sm">
        <button 
          onClick={() => setView('dashboard')}
          className="flex items-center text-charcoal font-medium group bg-white px-5 py-2.5 rounded-full border border-stone-200 hover:border-stone-300 shadow-sm hover:shadow-md transition-all active:scale-95"
        >
          <ArrowLeft className="w-4 h-4 mr-2 group-hover:-translate-x-1 transition-transform" />
          Dashboard
        </button>
        <span className="text-stone-500 text-sm font-serif italic bg-white/50 px-4 py-1.5 rounded-full border border-stone-100 hidden md:block">
          {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}
        </span>
      </div>

      {loading ? (
        <SkeletonLoader mode={loadingMode} />
