        <button 
          onClick={() => setView('dashboard')}
          className="flex items-center text-stone-500 hover:text-stone-900 transition-all duration-200 font-medium group mb-8 bg-white/50 px-4 py-2 rounded-full hover:bg-white border border-transparent hover:border-stone-200 w-fit active:scale-95"
