              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );

  const renderFooter = () => (
    <footer className="mt-24 pb-12 text-center text-stone-400 px-4 group/footer">
      <div className="max-w-2xl mx-auto border-t border-stone-200/50 pt-12 relative">
