            <p key={idx} className="text-stone-600 leading-relaxed font-sans text-[15px]">
              {paragraph}
            </p>
          ))}
        </div>
      </div>

      {/* Insights & Tips Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 border-t border-stone-100 text-xs">
        {/* Insights */}
        <div className="p-6 bg-[#FEFBF6]"> 
          <div className="flex items-center mb-4 text-amber-700/80 font-bold uppercase tracking-widest text-[10px]">
            <Lightbulb className="w-3.5 h-3.5 mr-2 text-amber-500 fill-amber-500/10" />
            Key Insights
          </div>
          <ul className="space-y-3">
            {article.insights.map((insight, idx) => (
