          </div>

          <div className="flex items-center space-x-3">
             {article.tweet_draft && (
                <button
                    onClick={handleCopyTweet}
                    className={`flex items-center space-x-2 px-3 py-1.5 rounded-full text-[11px] font-bold tracking-wide transition-all duration-300 active:scale-95 border ${copied ? 'text-blue-600 bg-blue-50 border-blue-100' : 'text-stone-400 border-transparent hover:text-blue-500 hover:bg-blue-50/50 hover:border-blue-100'}`}
                    title="Copy Tweet to Clipboard"
                >
                    {copied ? <Check className="w-3.5 h-3.5" /> : <Twitter className="w-3.5 h-3.5" />}
                    <span>{copied ? 'Copied' : 'Tweet'}</span>
                </button>
