                className={`flex items-center space-x-2 px-3 py-1.5 rounded-full text-[11px] font-bold tracking-wide transition-all duration-300 active:scale-95 border ${isSaved ? 'text-amber-800 bg-amber-50 border-amber-100 shadow-sm' : 'text-stone-500 border-transparent hover:bg-stone-100 hover:text-stone-900'}`}
