import { GoogleGenAI, Type } from "@google/genai";
import { Article, DigestConfig, UserPreferences } from "../types.ts";
import { FALLBACK_ARTICLES } from "../constants.ts";

// Switched to Flash model for faster inference and tool use
const MODEL_NAME = 'gemini-3-flash-preview';

/**
 * Clean JSON string if the model returns markdown code blocks or conversational text
 */
const cleanJsonString = (str: string): string => {
  let cleaned = str.trim();
  const codeBlockRegex = /```json\s*([\s\S]*?)\s*```/;
  const match = cleaned.match(codeBlockRegex);
  if (match) {
    cleaned = match[1];
  } else {
    const firstBrace = cleaned.indexOf('{');
    const firstBracket = cleaned.indexOf('[');
    let startIndex = -1;
    let endIndex = -1;

    if (firstBracket !== -1 && (firstBrace === -1 || firstBracket < firstBrace)) {
        startIndex = firstBracket;
        endIndex = cleaned.lastIndexOf(']');
    } else if (firstBrace !== -1) {
        startIndex = firstBrace;
        endIndex = cleaned.lastIndexOf('}');
    }

    if (startIndex !== -1 && endIndex !== -1) {
        cleaned = cleaned.substring(startIndex, endIndex + 1);
    }
  }
  return cleaned;
};

const getPreferenceContext = (prefs?: UserPreferences): string => {
  if (!prefs) return "";
  let context = "";
  if (prefs.likedArticles.length > 0) {
    const likedTitles = prefs.likedArticles.slice(0, 5).map(a => `"${a.title}"`).join(", ");
    context += `USER FEEDBACK - POSITIVE: User liked: ${likedTitles}. Prioritize similar quality/depth.\n`;
  }
  if (prefs.dislikedArticles.length > 0) {
    const dislikedTitles = prefs.dislikedArticles.slice(0, 5).map(a => `"${a.title}"`).join(", ");
    context += `USER FEEDBACK - NEGATIVE: User disliked: ${dislikedTitles}. Avoid similar content.\n`;
  }
  return context;
};

export async function fetchLiveDigest(config: DigestConfig, prefs?: UserPreferences): Promise<Article[]> {
  // Use direct process.env.API_KEY access as per guidelines
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const { level, topics, dateRange } = config;

  const topicsStr = topics.join(", ");
  const preferenceContext = getPreferenceContext(prefs);

  const prompt = `
    ACT AS: A Senior Product Design Lead.
    TASK: Find 4 unique, high-quality design articles or videos.
    DATE CONSTRAINT: Published within ${dateRange}.
    TARGET AUDIENCE LEVEL: ${level}.
    TOPICS: ${topicsStr}.
    ${preferenceContext}

    OUTPUT FORMAT: Return a valid JSON array of 4 Article objects. 
    Use Search to find EXACT, working URLs. No fabrications.

    Schema:
    [
      {
        "id": "uuid",
        "title": "Title",
        "author": "Author",
        "source": "Publication Name",
        "type": "Article" | "Video",
        "category": "Category",
        "url": "DIRECT_URL",
        "summary": ["Point 1", "Point 2", "Point 3"],
        "insights": ["Insight 1", "Insight 2", "Insight 3"],
        "application_tips": ["Tip 1", "Tip 2", "Tip 3"],
        "tweet_draft": "Mental model hook -> Value prop."
      }
    ]
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        // Optimize for speed by disabling thinking budget for this task
        thinkingConfig: { thinkingBudget: 0 }
      },
    });

    const text = response.text;
    if (!text) return FALLBACK_ARTICLES;
    return JSON.parse(cleanJsonString(text)) as Article[];
  } catch (error) {
    console.error("Gemini fetch failed:", error);
    return FALLBACK_ARTICLES;
  }
}

export async function analyzeUrl(url: string): Promise<Article> {
  // Use direct process.env.API_KEY access as per guidelines
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const prompt = `
    Analyze this URL: ${url}
    Act as a Product Designer. Extract core value and insights.

    OUTPUT FORMAT: Return a single JSON Article object.
    {
      "id": "uuid",
      "title": "Title",
      "author": "Author",
      "source": "Source",
      "type": "Article",
      "category": "Category",
      "url": "${url}",
      "summary": ["..."],
      "insights": ["..."],
      "application_tips": ["..."],
      "tweet_draft": "Insight hook."
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: { 
        tools: [{ googleSearch: {} }],
        // Optimize for speed
        thinkingConfig: { thinkingBudget: 0 }
      },
    });

    const text = response.text;
    if (!text) throw new Error("Empty response");
    return JSON.parse(cleanJsonString(text)) as Article;
  } catch (error) {
    console.error("Analysis failed:", error);
    throw error;
  }
}

import React, { useState, useEffect } from 'react';
import { Loader2, Sparkles, CheckCircle2, Circle, BrainCircuit, PenTool, Search, Share2 } from 'lucide-react';

interface SkeletonLoaderProps {
  mode?: 'feed' | 'url';
}

const FEED_STEPS = [
  { text: "Scanning knowledge graph", icon: BrainCircuit },
  { text: "Sourcing reputable articles", icon: Search },
  { text: "Extracting insights", icon: Share2 },
  { text: "Synthesizing briefing", icon: Sparkles },
  { text: "Final polish", icon: PenTool }
];

const URL_STEPS = [
  { text: "Analyzing resource", icon: Search },
  { text: "Decoding structure", icon: BrainCircuit },
  { text: "Extracting core value", icon: Sparkles },
  { text: "Generating action tips", icon: PenTool },
  { text: "Finalizing", icon: CheckCircle2 }
];

const SkeletonLoader: React.FC<SkeletonLoaderProps> = ({ mode = 'feed' }) => {
  const [currentStep, setCurrentStep] = useState(0);
  const steps = mode === 'url' ? URL_STEPS : FEED_STEPS;
  const progress = Math.min(((currentStep + 0.5) / steps.length) * 100, 100);

  useEffect(() => {
    // Accelerated timing to match faster Gemini Flash model response
    const times = [600, 800, 700, 600, 500];

    const advance = () => {
      setCurrentStep((prev) => {
        if (prev < steps.length - 1) {
          return prev + 1;
        }
        return prev;
      });
    };

    let timeoutId: ReturnType<typeof setTimeout>;

    const scheduleNext = (stepIndex: number) => {
      if (stepIndex < steps.length - 1) {
        timeoutId = setTimeout(() => {
          advance();
          scheduleNext(stepIndex + 1);
        }, times[stepIndex] || 600);
      }
    };

    scheduleNext(0);

    return () => clearTimeout(timeoutId);
  }, [steps.length]);

  const CurrentIcon = steps[currentStep].icon;

  return (
    <div className="w-full max-w-2xl mx-auto py-24 px-4">
      <div className="text-center mb-12 relative">
        {/* Central Pulse Animation */}
        <div className="relative inline-flex items-center justify-center mb-8">
          <div className="absolute inset-0 bg-stone-200 rounded-full animate-[ping_1.5s_ease-in-out_infinite] opacity-40"></div>
          <div className="absolute inset-0 bg-stone-100 rounded-full animate-[pulse_2s_ease-in-out_infinite]"></div>
          <div className="relative bg-white p-4 rounded-full shadow-sm border border-stone-100">
             <CurrentIcon className="w-8 h-8 text-charcoal animate-[spin_3s_linear_infinite]" strokeWidth={1.5} />
          </div>
        </div>

        <h3 className="font-serif text-3xl text-charcoal mb-3 animate-in fade-in slide-in-from-bottom-2 duration-500 key={currentStep}">
          {steps[currentStep].text}...
        </h3>

        {/* Progress Bar */}
        <div className="max-w-xs mx-auto mt-6">
          <div className="h-1 w-full bg-stone-100 rounded-full overflow-hidden">
            <div 
              className="h-full bg-charcoal transition-all duration-500 ease-out"
              style={{ width: `${progress}%` }}
            />
          </div>
        </div>
      </div>

      <div className="bg-white/50 backdrop-blur-sm rounded-2xl border border-stone-100 p-8 shadow-sm max-w-lg mx-auto space-y-5">
        {steps.map((step, index) => {
          const isActive = index === currentStep;
          const isCompleted = index < currentStep;

          return (
            <div 
              key={index} 
              className={`flex items-center transition-all duration-300 ${
                index > currentStep ? 'opacity-30 blur-[0.5px]' : 'opacity-100'
              }`}
            >
              <div className={`mr-4 flex-shrink-0 transition-all duration-300 ${
                isCompleted ? 'text-green-600 scale-110' : isActive ? 'text-charcoal scale-110' : 'text-stone-300'
              }`}>
                {isCompleted ? (
                  <CheckCircle2 className="w-5 h-5" />
                ) : isActive ? (
                  <Loader2 className="w-5 h-5 animate-spin" />
                ) : (
                  <Circle className="w-5 h-5" />
                )}
              </div>
              <span className={`text-sm font-medium font-sans transition-colors duration-300 ${
                isActive ? 'text-charcoal' : 'text-stone-500'
              }`}>
                {step.text}
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
};

