    OUTPUT FORMAT: Return a single JSON Article object.
    {
      "id": "uuid",
      "title": "Title",
      "author": "Author",
      "source": "Source",
      "type": "Article",
      "category": "Category",
      "url": "${url}",
      "date": "Month DD, YYYY",
      "summary": ["..."],
      "insights": ["Deep Insight 1", "Deep Insight 2", "Deep Insight 3", "Deep Insight 4", "Deep Insight 5"],
      "application_tips": ["Actionable Tip 1", "Actionable Tip 2", "Actionable Tip 3", "Actionable Tip 4", "Actionable Tip 5"],
      "tweet_draft": "Write a Naval Ravikant style tweet (2 sentences max). Pure wisdom/insight only. No hashtags, no links. Concise, punchy, high-signal."
    }
