  const [savedArticles, setSavedArticles] = useState<Article[]>([]);
  const [likedArticles, setLikedArticles] = useState<Article[]>([]);
  const [dislikedArticles, setDislikedArticles] = useState<Article[]>([]);
  const [isFallbackMode, setIsFallbackMode] = useState(false);

  const [config, setConfig] = useState<DigestConfig>({
    level: 'Mid-Level',
    topics: ['Random/Surprise Me'],
    dateRange: 'Last Month'
  });

  const [currentQuote, setCurrentQuote] = useState(DESIGN_QUOTES[0]);

  useEffect(() => {
    setCurrentQuote(DESIGN_QUOTES[Math.floor(Math.random() * DESIGN_QUOTES.length)]);

    // Load local data
    try {
      const h = localStorage.getItem('ddd_history');
      if (h) setHistory(JSON.parse(h));
      const s = localStorage.getItem('ddd_saved');
      if (s) setSavedArticles(JSON.parse(s));
      const l = localStorage.getItem('ddd_liked');
      if (l) setLikedArticles(JSON.parse(l));
      const d = localStorage.getItem('ddd_disliked');
      if (d) setDislikedArticles(JSON.parse(d));
    } catch (e) {
      console.error("Storage error:", e);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('ddd_history', JSON.stringify(history));
    localStorage.setItem('ddd_saved', JSON.stringify(savedArticles));
    localStorage.setItem('ddd_liked', JSON.stringify(likedArticles));
    localStorage.setItem('ddd_disliked', JSON.stringify(dislikedArticles));
  }, [history, savedArticles, likedArticles, dislikedArticles]);

  const handleNewQuote = () => {
    setCurrentQuote(DESIGN_QUOTES[Math.floor(Math.random() * DESIGN_QUOTES.length)]);
  };

  const handleGenerateDigest = async () => {
    setLoading(true);
    setLoadingMode('feed');
    setView('result');
    setArticles([]); 
    setIsFallbackMode(false);

    try {
      const { fetchLiveDigest } = await import('./services/geminiService.ts');
      const results = await fetchLiveDigest(config, { likedArticles, dislikedArticles });

      if (results === FALLBACK_ARTICLES) {
        setIsFallbackMode(true);
      }

      setArticles(results);

      const historyItem: DigestHistoryItem = {
        id: generateId(),
        timestamp: Date.now(),
        config,
        articles: results,
        type: 'feed'
      };
      setHistory(prev => [historyItem, ...prev]);
    } catch (err) {
      console.error("Fetch failed:", err);
      alert("Briefing generation failed. Please check your internet connection or verify your API key.");
    } finally {
      setLoading(false);
    }
  };

  const handleAnalyzeUrl = async (url: string) => {
    setLoading(true);
    setLoadingMode('url');
    setView('result');
    setArticles([]);
    setIsFallbackMode(false);

    try {
      const { analyzeUrl } = await import('./services/geminiService.ts');
      const result = await analyzeUrl(url);
      setArticles([result]);

      const historyItem: DigestHistoryItem = {
        id: generateId(),
        timestamp: Date.now(),
        config: { level: config.level, topics: [], dateRange: 'Any Time' }, 
        articles: [result],
        type: 'url'
      };
      setHistory(prev => [historyItem, ...prev]);
    } catch (err) {
      console.error("Analysis failed:", err);
      alert("URL Analysis failed.");
    } finally {
      setLoading(false);
    }
  };

  const handleToggleSave = (article: Article) => {
    setSavedArticles(prev => prev.some(a => a.url === article.url) 
      ? prev.filter(a => a.url !== article.url) 
      : [article, ...prev]
    );
  };

  const handleRate = (article: Article, rating: 'up' | 'down' | null) => {
    setLikedArticles(prev => prev.filter(a => a.url !== article.url));
    setDislikedArticles(prev => prev.filter(a => a.url !== article.url));
    if (rating === 'up') setLikedArticles(prev => [article, ...prev]);
    else if (rating === 'down') setDislikedArticles(prev => [article, ...prev]);
  };

  const renderFloatingControls = () => (
    <div className="fixed top-4 right-4 md:top-6 md:right-6 z-50 flex flex-col items-end gap-4 pointer-events-none">
      <div className="flex gap-1 pointer-events-auto bg-white/80 backdrop-blur-xl p-1.5 rounded-full shadow-lg border border-white/50 ring-1 ring-stone-900/5 transition-all">
        <button
            onClick={() => setView('dashboard')}
            className={`p-3 rounded-full transition-all ${view === 'dashboard' ? 'text-charcoal bg-stone-100' : 'text-stone-400 hover:text-stone-600'}`}
        >
             <Home className="w-5 h-5" />
        </button>
        <button 
          onClick={() => setView('saved')}
          className={`relative p-3 rounded-full transition-all ${view === 'saved' ? 'text-amber-700 bg-amber-50' : 'text-stone-400 hover:text-amber-600'}`}
        >
          <Bookmark className={`w-5 h-5 ${view === 'saved' ? 'fill-current' : ''}`} />
          {savedArticles.length > 0 && (
            <span className="absolute top-2 right-2 w-2 h-2 bg-amber-500 rounded-full border border-white"></span>
          )}
        </button>
        <button 
          onClick={() => setView('history')}
          className={`p-3 rounded-full transition-all ${view === 'history' ? 'text-charcoal bg-stone-100' : 'text-stone-400 hover:text-stone-600'}`}
        >
          <History className="w-5 h-5" />
        </button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen font-sans text-charcoal selection:bg-stone-200 flex flex-col bg-cream relative">
      {!process.env.API_KEY && <ApiKeyInput onSave={(key) => {
         // Logic to save API key would go here if not using env var,
         // but for this specific instruction we rely on env vars/build config.
         // This component is kept to satisfy imports but hidden via check.
         console.log("Saving key", key);
      }} />}

      {renderFloatingControls()}
      <main className="max-w-6xl mx-auto px-4 flex-grow w-full">
        {view === 'dashboard' && (
          <div className="space-y-8 md:space-y-12 pt-20 md:pt-32 animate-in fade-in duration-700">
            <section className="text-center space-y-4 md:space-y-6">
              <div className="inline-flex items-center justify-center p-2 bg-stone-100 rounded-full mb-2">
                  <Sparkles className="w-4 h-4 text-stone-400" />
              </div>
              <h1 className="font-serif text-4xl md:text-7xl lg:text-8xl text-charcoal tracking-tighter leading-[0.9]">
                Daily Design <br/>
                <span className="text-stone-400 italic font-light">Digest</span>
              </h1>
              <p className="text-stone-500 text-lg md:text-xl font-serif italic max-w-lg mx-auto leading-relaxed px-4">
                Curated intelligence for product designers, strategists, and engineers.
              </p>
            </section>
            <DigestConfigurator config={config} setConfig={setConfig} onGenerate={handleGenerateDigest} isLoading={loading} />
            <UrlAnalyzer onAnalyze={handleAnalyzeUrl} isLoading={loading} />
          </div>
        )}

        {view === 'result' && (
          <div className="pt-20 md:pt-24 animate-in slide-in-from-bottom-4 duration-500">
            <div className="mb-6 md:mb-10 flex flex-col md:flex-row items-start md:items-center justify-between sticky top-4 md:top-6 z-30 pointer-events-none gap-4">
              <div className="flex items-center gap-2 pointer-events-auto bg-cream/90 backdrop-blur-md p-2 rounded-full border border-stone-100 shadow-sm">
                <button onClick={() => setView('dashboard')} className="flex items-center text-charcoal font-medium bg-white px-4 py-2 rounded-full border border-stone-200 shadow-sm hover:shadow-md transition-all text-sm">
                    <ArrowLeft className="w-4 h-4 mr-2" />
                    Dashboard
                </button>
              </div>

              <span className="text-stone-500 text-xs md:text-sm font-serif italic hidden md:block bg-cream/90 backdrop-blur-md px-4 py-2 rounded-full border border-stone-100">
                {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}
              </span>
            </div>

            {isFallbackMode && (
              <div className="mb-8 p-4 bg-amber-50 border border-amber-200 rounded-xl flex items-start animate-in fade-in slide-in-from-top-2">
                <div className="p-2 bg-amber-100 rounded-full mr-4 flex-shrink-0 text-amber-600">
                   <AlertTriangle className="w-5 h-5" />
                </div>
                <div>
                   <h4 className="text-amber-900 font-bold text-sm uppercase tracking-wide mb-1">AI Connection Unavailable</h4>
                   <p className="text-amber-800 text-sm leading-relaxed">
                     We couldn't connect to the live intelligence feed (Check your API Key or Network). 
                     <br className="hidden md:block"/>
                     Showing <strong>curated sample data</strong> so you can still experience the interface.
                   </p>
                </div>
              </div>
            )}

            {loading ? <SkeletonLoader mode={loadingMode} /> : (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-8 pb-20">
                {articles.map(article => (
                  <ArticleCard 
                    key={article.url} 
                    article={article} 
                    isSaved={savedArticles.some(a => a.url === article.url)}
                    rating={likedArticles.some(a => a.url === article.url) ? 'up' : dislikedArticles.some(a => a.url === article.url) ? 'down' : null}
                    onToggleSave={handleToggleSave}
                    onRate={handleRate}
                  />
                ))}
              </div>
            )}
          </div>
        )}

        {(view === 'saved' || view === 'history') && (
           <div className="pt-20 md:pt-24 animate-in fade-in duration-300 max-w-4xl mx-auto">
             <button onClick={() => setView('dashboard')} className="flex items-center text-stone-500 hover:text-stone-900 transition-all font-medium mb-8">
               <ArrowLeft className="w-4 h-4 mr-2" />
               Dashboard
             </button>
             <h2 className="font-serif text-4xl md:text-5xl mb-8 md:mb-12 text-charcoal tracking-tight capitalize">{view}</h2>

             {view === 'saved' && (
               <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-8 pb-20">
                 {savedArticles.length === 0 ? <p className="col-span-full text-center py-20 text-stone-400 italic">No saved articles yet.</p> : 
                   savedArticles.map(article => (
                     <ArticleCard key={article.url} article={article} isSaved={true} onToggleSave={handleToggleSave} onRate={handleRate} />
                   ))
                 }
               </div>
             )}

             {view === 'history' && (
                <div className="space-y-4 md:space-y-6 pb-20">
                  {history.length === 0 ? <p className="text-center py-20 text-stone-400 italic">History is empty.</p> : 
                    history.map(item => (
                      <div key={item.id} onClick={() => {setArticles(item.articles); setView('result');}} className="bg-white p-5 md:p-6 rounded-2xl border border-stone-200 hover:shadow-lg cursor-pointer transition-all flex justify-between items-center group">
                        <div>
                          <p className="text-[10px] font-bold text-stone-400 uppercase tracking-widest mb-2">
                            {new Date(item.timestamp).toLocaleString()}
                          </p>
                          <h3 className="font-serif text-lg md:text-xl text-charcoal line-clamp-1">{item.type === 'url' ? item.articles[0].title : `${item.articles.length} Articles Briefing`}</h3>
                        </div>
                        <ArrowLeft className="w-5 h-5 rotate-180 text-stone-300 group-hover:text-charcoal group-hover:translate-x-1 transition-all flex-shrink-0 ml-4" />
                      </div>
                    ))
                  }
                </div>
             )}
           </div>
        )}
      </main>

      <footer className="mt-12 md:mt-24 pb-12 text-center text-stone-400 group/footer px-4">
        <div className="max-w-2xl mx-auto border-t border-stone-200/50 pt-12 relative">
          <Quote className="w-5 h-5 opacity-40 text-stone-400 mx-auto mb-6" />
          <p className="font-serif text-lg md:text-xl text-stone-600 mb-3 italic">"{currentQuote.text}"</p>
          <p className="text-xs font-bold uppercase tracking-widest">— {currentQuote.author}</p>
          <button onClick={handleNewQuote} className="mt-6 p-2 rounded-full text-stone-300 hover:text-stone-500 opacity-0 group-hover/footer:opacity-100 transition-all">
            <Shuffle className="w-4 h-4" />
          </button>
        </div>
      </footer>
    </div>
  );
}

export default function App() {
  return (
    <SimpleErrorBoundary>
      <AppContent />
    </SimpleErrorBoundary>
  );
}

import React, { useState } from 'react';
import { ExternalLink, Lightbulb, Zap, BookOpen, PlayCircle, Bookmark, ThumbsUp, ThumbsDown, Twitter, Check, Calendar } from 'lucide-react';
