        </div>

        <h2 className="font-serif text-xl md:text-2xl font-bold leading-tight text-charcoal mb-3 group-hover:text-black transition-colors text-balance">
          <a href={article.url} target="_blank" rel="noopener noreferrer" className="hover:underline decoration-stone-300 underline-offset-[6px] decoration-2">
