                 <ArrowLeft className="w-4 h-4 text-stone-600 group-hover:text-charcoal" />
              </div>
              <span className="font-serif text-sm font-medium text-stone-600 group-hover:text-charcoal tracking-wide">Dashboard</span>
            </button>
          )}
        </div>

        {/* Right: Navigation Tabs */}
        <div className="pointer-events-auto shadow-[0_2px_8px_rgba(0,0,0,0.04)] bg-white/90 backdrop-blur-xl p-1.5 rounded-full border border-stone-200/50 flex gap-1 items-center">
             <button
