        <div className="pointer-events-auto shadow-[0_2px_8px_rgba(0,0,0,0.04)] bg-white/90 backdrop-blur-xl p-1.5 rounded-full border border-stone-200/50 flex gap-1 items-center">
             <button
                onClick={() => setView('dashboard')}
                className={`p-2.5 rounded-full transition-all duration-300 ${
                  view === 'dashboard' 
                    ? 'bg-stone-100 text-charcoal shadow-inner' 
                    : 'text-stone-400 hover:text-stone-600 hover:bg-stone-50'
                }`}
                title="Home"
            >
                 <Home className="w-5 h-5" />
            </button>
            <button 
              onClick={() => setView('saved')}
              className={`relative p-2.5 rounded-full transition-all duration-300 ${
                view === 'saved' 
                  ? 'bg-amber-50 text-amber-900 shadow-inner' 
                  : 'text-stone-400 hover:text-amber-700 hover:bg-amber-50/50'
              }`}
              title="Saved Articles"
            >
              <Bookmark className={`w-5 h-5 ${view === 'saved' ? 'fill-current' : ''}`} />
              {savedArticles.length > 0 && (
                <span className="absolute top-2 right-2 w-1.5 h-1.5 bg-amber-500 rounded-full ring-1 ring-white"></span>
              )}
            </button>
            <button 
              onClick={() => setView('history')}
              className={`p-2.5 rounded-full transition-all duration-300 ${
                view === 'history' 
                  ? 'bg-stone-100 text-charcoal shadow-inner' 
                  : 'text-stone-400 hover:text-stone-600 hover:bg-stone-50'
              }`}
              title="History"
            >
              <History className="w-5 h-5" />
            </button>
        </div>
      </div>
    </nav>
  );

  return (
    <div className="min-h-screen font-sans text-charcoal selection:bg-stone-200 flex flex-col bg-cream relative">

      {renderNavBar()}

      <main className="max-w-6xl mx-auto px-4 flex-grow w-full pt-24 md:pt-32">
        {view === 'dashboard' && (
          <div className="space-y-8 md:space-y-12 animate-in fade-in duration-700">
            <section className="text-center space-y-4 md:space-y-6">
              <div className="inline-flex items-center justify-center p-2 bg-stone-100 rounded-full mb-2">
                  <Sparkles className="w-4 h-4 text-stone-400" />
              </div>
              <h1 className="font-display text-5xl md:text-7xl lg:text-9xl text-charcoal leading-[0.9] pt-2">
                Daily Design <br/>
                <span className="text-stone-400">Digest</span>
              </h1>
              <p className="text-stone-500 text-lg md:text-xl font-sans italic max-w-lg mx-auto leading-relaxed px-4">
                Curated intelligence for product designers, strategists, and engineers.
              </p>
            </section>
            <DigestConfigurator config={config} setConfig={setConfig} onGenerate={handleGenerateDigest} isLoading={loading} />
            <UrlAnalyzer onAnalyze={handleAnalyzeUrl} isLoading={loading} />
          </div>
        )}

        {view === 'result' && (
          <div className="animate-in slide-in-from-bottom-4 duration-500">
            {isFallbackMode && (
              <div className="mb-8 p-4 bg-amber-50 border border-amber-200 rounded-xl flex items-start animate-in fade-in slide-in-from-top-2">
                <div className="p-2 bg-amber-100 rounded-full mr-4 flex-shrink-0 text-amber-600">
                   <AlertTriangle className="w-5 h-5" />
                </div>
                <div>
                   <h4 className="text-amber-900 font-bold text-sm uppercase tracking-wide mb-1">AI Connection Unavailable</h4>
                   <p className="text-amber-800 text-sm leading-relaxed">
                     We couldn't connect to the live intelligence feed (Check your API Key or Network). 
                     <br className="hidden md:block"/>
                     Showing <strong>curated sample data</strong> so you can still experience the interface.
                   </p>
                </div>
              </div>
            )}

            {loading ? <SkeletonLoader mode={loadingMode} /> : (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-8 pb-20">
                {articles.map(article => (
                  <ArticleCard 
                    key={article.url} 
                    article={article} 
                    isSaved={savedArticles.some(a => a.url === article.url)}
                    rating={likedArticles.some(a => a.url === article.url) ? 'up' : dislikedArticles.some(a => a.url === article.url) ? 'down' : null}
                    onToggleSave={handleToggleSave}
                    onRate={handleRate}
                  />
                ))}
              </div>
            )}
          </div>
        )}

        {(view === 'saved' || view === 'history') && (
           <div className="animate-in fade-in duration-300 max-w-4xl mx-auto">
             <h2 className="font-display text-5xl md:text-7xl mb-8 md:mb-12 text-charcoal tracking-tight capitalize">{view}</h2>

             {view === 'saved' && (
               <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-8 pb-20">
                 {savedArticles.length === 0 ? <p className="col-span-full text-center py-20 text-stone-400 italic">No saved articles yet.</p> : 
                   savedArticles.map(article => (
                     <ArticleCard key={article.url} article={article} isSaved={true} onToggleSave={handleToggleSave} onRate={handleRate} />
                   ))
                 }
               </div>
             )}

             {view === 'history' && (
                <div className="space-y-4 md:space-y-6 pb-20">
                  {history.length === 0 ? <p className="text-center py-20 text-stone-400 italic">History is empty.</p> : 
                    history.map(item => (
                      <div 
                        key={item.id} 
                        onClick={() => {setArticles(item.articles); setView('result');}} 
                        className="bg-white p-5 md:p-6 rounded-2xl border border-stone-200 hover:shadow-[0_8px_30px_rgb(0,0,0,0.04)] hover:border-stone-300 cursor-pointer transition-all group relative overflow-hidden"
                      >
                        {/* Hover Indicator Line */}
                        <div className="absolute left-0 top-0 bottom-0 w-1 bg-charcoal transform -translate-x-full group-hover:translate-x-0 transition-transform duration-300" />

                        <div className="flex justify-between items-start mb-3">
                           <div className="flex items-center gap-2">
                              <span className="text-[10px] font-bold text-stone-400 uppercase tracking-widest bg-stone-50 px-2 py-1 rounded-md border border-stone-100">
                                {new Date(item.timestamp).toLocaleDateString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
                              </span>
                              {item.type === 'feed' && (
                                 <span className="text-[10px] font-bold text-stone-500 bg-white px-2 py-1 rounded-md border border-stone-200 uppercase tracking-widest flex items-center gap-1">
                                    <Filter className="w-3 h-3" />
                                    {item.config.level}
                                 </span>
                              )}
                           </div>
                           <div className="p-2 bg-stone-50 rounded-full group-hover:bg-charcoal group-hover:text-white transition-colors">
                              <ChevronRight className="w-4 h-4" />
                           </div>
                        </div>

                        <h3 className="font-sans text-xl md:text-2xl font-bold text-charcoal mb-4 group-hover:text-black transition-colors leading-tight">
                          {item.type === 'url' ? (
                            <span className="flex items-center gap-2">
                               <Link className="w-5 h-5 text-stone-400 flex-shrink-0" />
                               {item.articles[0]?.title || "URL Analysis"}
                            </span>
                          ) : (
                            `${item.articles.length} Articles Briefing`
                          )}
                        </h3>

                        {item.type === 'feed' && item.config.topics && (
                          <div className="flex flex-wrap gap-2 mt-auto">
                            {item.config.topics.map((topic, i) => (
                              <span key={i} className="inline-flex items-center px-2 py-1 rounded-md text-[11px] font-medium bg-stone-100 text-stone-600 border border-stone-200">
                                 <Tag className="w-3 h-3 mr-1 opacity-50" />
                                 {topic}
                              </span>
                            ))}
                          </div>
                        )}

                        {item.type === 'url' && (
                            <div className="text-sm text-stone-500 line-clamp-1 font-sans italic">
                                {item.articles[0]?.summary?.[0] || "No summary available."}
                            </div>
                        )}
                      </div>
                    ))
                  }
                </div>
             )}
           </div>
        )}
      </main>

      <footer className="mt-12 md:mt-24 pb-12 text-center text-stone-400 group/footer px-4">
        <div className="max-w-2xl mx-auto border-t border-stone-200/50 pt-12 relative">
          <Quote className="w-5 h-5 opacity-40 text-stone-400 mx-auto mb-6" />
          <p className="font-sans text-lg md:text-xl text-stone-600 mb-3 italic">"{currentQuote.text}"</p>
          <p className="text-xs font-bold uppercase tracking-widest">— {currentQuote.author}</p>
          <button onClick={handleNewQuote} className="mt-6 p-2 rounded-full text-stone-300 hover:text-stone-500 opacity-0 group-hover/footer:opacity-100 transition-all">
            <Shuffle className="w-4 h-4" />
          </button>
        </div>
      </footer>
    </div>
  );
}

export default function App() {
  return (
    <SimpleErrorBoundary>
      <AppContent />
    </SimpleErrorBoundary>
  );
}

import React from 'react';
import { DigestConfig, ExperienceLevel, Topic, DateRange } from '../types.ts';
import { AVAILABLE_TOPICS } from '../constants.ts';
import { RefreshCw, Check, Clock, Brain, Sparkles, Palette, Compass, Grid, Microscope, FileText, Users, Shuffle } from 'lucide-react';

interface DigestConfiguratorProps {
  config: DigestConfig;
  setConfig: React.Dispatch<React.SetStateAction<DigestConfig>>;
  onGenerate: () => void;
  isLoading: boolean;
}

const TOPIC_ICONS: Record<Topic, React.ElementType> = {
  'Product Thinking': Brain,
  'AI in UX': Sparkles,
  'Visual Design': Palette,
  'Strategy': Compass,
  'Design Systems': Grid,
  'Research': Microscope,
  'Product Design Case Studies': FileText,
  'UX Design Case Studies': Users,
  'Random/Surprise Me': Shuffle
};

const DigestConfigurator: React.FC<DigestConfiguratorProps> = ({ config, setConfig, onGenerate, isLoading }) => {

  const toggleTopic = (topic: Topic) => {
    setConfig(prev => {
      // If selecting Random, clear others and just set Random
      if (topic === 'Random/Surprise Me') {
        return { ...prev, topics: ['Random/Surprise Me'] };
      }

      // Filter out Random from the existing list (since we are interacting with specific topics)
      const currentTopicsWithoutRandom = prev.topics.filter(t => t !== 'Random/Surprise Me');

      if (prev.topics.includes(topic)) {
        // We are deselecting a topic
        const remaining = currentTopicsWithoutRandom.filter(t => t !== topic);

        // If nothing is left, default back to Random/Surprise Me
        if (remaining.length === 0) {
          return { ...prev, topics: ['Random/Surprise Me'] };
        }

        return { ...prev, topics: remaining };
      } else {
        // We are adding a topic
        return { ...prev, topics: [...currentTopicsWithoutRandom, topic] };
      }
    });
  };

  const handleLevelChange = (level: ExperienceLevel) => {
    setConfig(prev => ({ ...prev, level }));
  };

  const handleDateRangeChange = (dateRange: DateRange) => {
    setConfig(prev => ({ ...prev, dateRange }));
  };

  const dateRanges: DateRange[] = ['Last 24 Hours', 'Last Week', 'Last Month', 'Last 6 Months', 'Any Time'];
  const currentIndex = dateRanges.indexOf(config.dateRange);

  const levels: { id: ExperienceLevel; title: string; subtitle: string }[] = [
    { id: 'Junior', title: 'Junior', subtitle: 'Foundations & Core Concepts' },
    { id: 'Mid-Level', title: 'Mid-Level', subtitle: 'Execution & Detailed Analysis' },
    { id: 'Senior', title: 'Senior', subtitle: 'Strategy, Systems & Leadership' },
  ];

  // Restored: No longer filtering out Random/Surprise Me
  const displayTopics = AVAILABLE_TOPICS;

  return (
    <div className="bg-white rounded-2xl p-5 md:p-8 shadow-sm max-w-4xl mx-auto mb-12 relative overflow-hidden group">
      <div className="relative z-10 flex flex-col md:flex-row gap-6 md:gap-12">

        {/* Left Column: Level */}
        <div className="flex-shrink-0 md:w-1/3 space-y-6 md:space-y-8">

          {/* Experience Level */}
          <div className="space-y-3 md:space-y-4">
            {levels.map((lvl) => {
              const isSelected = config.level === lvl.id;
              return (
                <button
                  key={lvl.id}
                  onClick={() => handleLevelChange(lvl.id)}
                  className={`
                    w-full relative px-3 py-2.5 md:px-4 md:py-3 text-left rounded-xl text-sm font-medium transition-all duration-200 ease-out border active:scale-[0.98]
                    ${isSelected 
                      ? 'bg-stone-900 border-stone-900 text-white shadow-lg shadow-stone-200 transform scale-[1.02] ring-2 ring-offset-2 ring-stone-900' 
                      : 'bg-white border-stone-200 text-stone-600 hover:border-stone-300 hover:bg-stone-50 hover:shadow-sm'
                    }
                  `}
                >
                  <div className="flex justify-between items-center">
                    <span className="font-sans font-bold text-base tracking-tight block mb-0.5">
                      {lvl.title}
                    </span>
                    {isSelected && <Check className="w-4 h-4 text-amber-200" />}
                  </div>
                  <span className={`text-[10px] uppercase tracking-wide opacity-80 ${isSelected ? 'text-stone-300' : 'text-stone-400'}`}>
                    {lvl.subtitle}
                  </span>
                </button>
              );
            })}
          </div>
        </div>

        {/* Right Column: Topics & Timeframe Slider */}
        <div className="flex-grow space-y-6 border-t pt-6 md:pt-0 md:border-t-0 md:border-l border-stone-100 pl-0 md:pl-10 flex flex-col">
           <div className="flex items-center text-xs font-bold uppercase tracking-widest text-stone-400 mb-1 pl-1 md:hidden">
              Topics
            </div>

          <div className="grid grid-cols-2 gap-3">
            {displayTopics.map((topic) => {
              const isSelected = config.topics.includes(topic);
              const isRandom = topic === 'Random/Surprise Me';
              const Icon = TOPIC_ICONS[topic] || Check;
              return (
                <button
                  key={topic}
                  onClick={() => toggleTopic(topic)}
                  className={`
                    flex items-center px-3 py-3 rounded-xl text-xs md:text-sm font-medium border transition-all duration-200 active:scale-95 text-left
                    ${isRandom ? 'col-span-2 justify-center' : ''}
                    ${isSelected
                      ? 'bg-stone-800 border-stone-800 text-white shadow-md ring-2 ring-offset-1 ring-stone-800'
                      : 'bg-white border-stone-200 text-stone-600 hover:border-stone-300 hover:text-stone-900 hover:bg-stone-50'
                    }
                  `}
                >
                  <Icon className={`w-4 h-4 mr-2.5 flex-shrink-0 ${isSelected ? 'text-amber-200' : 'text-stone-400'}`} />
                  <span className="truncate">{topic}</span>
                </button>
              );
            })}
          </div>

          {/* Timeframe Slider Section */}
          <div className="mt-auto pt-6 border-t border-stone-100/50">
             <div className="flex items-center justify-between mb-4 px-1">
                <div className="flex items-center text-xs font-bold uppercase tracking-widest text-stone-400">
                  <Clock className="w-3 h-3 mr-1.5" />
                  Timeframe
                </div>
                <span className="text-charcoal bg-stone-100 px-2.5 py-1 rounded text-[10px] border border-stone-200 font-bold tracking-wide">
                  {config.dateRange}
                </span>
             </div>

             <div className="relative px-2 pb-2">
                <input
                  type="range"
                  min="0"
                  max={dateRanges.length - 1}
                  step="1"
                  value={currentIndex}
                  onChange={(e) => handleDateRangeChange(dateRanges[parseInt(e.target.value)])}
                  className="w-full h-1.5 bg-stone-200 rounded-lg appearance-none cursor-pointer accent-stone-800 focus:outline-none focus:ring-2 focus:ring-stone-200"
                />
                <div className="flex justify-between mt-3 text-[9px] text-stone-400 font-bold uppercase tracking-widest select-none">
                  <span>24h</span>
                  <span>Week</span>
                  <span>Month</span>
                  <span>6M</span>
                  <span>All</span>
                </div>
             </div>
          </div>

          {/* Generate Button - Moved inside the right column for better alignment */}
          <div className="pt-4">
            <button
                onClick={onGenerate}
                disabled={isLoading || config.topics.length === 0}
                className={`
                w-full group relative flex items-center justify-center px-8 py-4 rounded-full font-sans font-bold text-lg shadow-xl transition-all duration-300
                ${isLoading 
                    ? 'bg-stone-100 text-stone-400 cursor-not-allowed translate-y-0 shadow-none' 
                    : 'bg-charcoal text-white hover:bg-black hover:-translate-y-1 hover:shadow-2xl hover:shadow-charcoal/20 active:translate-y-0 active:scale-95'
                }
                `}
            >
                {isLoading ? (
                <span className="flex items-center">
                    <RefreshCw className="mr-2 w-5 h-5 animate-spin" />
                    Synthesizing...
                </span>
                ) : (
                <>
                    <span className="relative z-10">Generate Briefing</span>
                    <RefreshCw className="ml-3 w-5 h-5 transition-transform group-hover:rotate-180" />
                </>
                )}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DigestConfigurator;

import React, { useState } from 'react';
import { ExternalLink, Lightbulb, Zap, BookOpen, PlayCircle, Bookmark, ThumbsUp, ThumbsDown, Twitter, Check, Calendar } from 'lucide-react';
import { Article } from '../types.ts';

interface ArticleCardProps {
  article: Article;
  isSaved?: boolean;
  rating?: 'up' | 'down' | null;
  onToggleSave?: (article: Article) => void;
  onRate?: (article: Article, rating: 'up' | 'down' | null) => void;
}

const ArticleCard: React.FC<ArticleCardProps> = ({ 
  article, 
  isSaved = false, 
  rating = null, 
  onToggleSave, 
  onRate 
}) => {
  const [copied, setCopied] = useState(false);

  const handleCopyTweet = () => {
    // Tweet body only, no URL appending as per request
    const tweetBody = article.tweet_draft || `${article.title} by ${article.author}`;

    navigator.clipboard.writeText(tweetBody).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }).catch(err => {
      console.error("Failed to copy tweet", err);
    });
  };

  return (
    <article className="group bg-[#FEFBF6] border border-stone-200/60 rounded-xl overflow-hidden transition-all duration-300 hover:shadow-[0_8px_30px_rgb(0,0,0,0.04)] hover:border-stone-300 hover:-translate-y-1 flex flex-col h-full relative">
      {/* Header - Compact & High Contrast */}
      <div className="p-5 md:p-6 pb-2">
        <div className="flex justify-between items-start mb-3">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="inline-flex items-center px-2.5 py-0.5 rounded-md text-[10px] font-extrabold bg-stone-900 text-white border border-stone-900 uppercase tracking-widest shadow-sm">
              {article.category}
            </span>
            {article.date && (
                <span className="inline-flex items-center text-[10px] text-stone-400 font-semibold tracking-wide ml-1">
                  <Calendar className="w-3 h-3 mr-1 opacity-50" />
                  {article.date}
                </span>
            )}
          </div>
          <div className="p-1.5 bg-white border border-stone-100 rounded-full shadow-sm flex-shrink-0">
            {article.type === 'Video' ? (
                <PlayCircle className="w-4 h-4 text-stone-400 group-hover:text-charcoal transition-colors" />
            ) : (
                <BookOpen className="w-4 h-4 text-stone-400 group-hover:text-charcoal transition-colors" />
            )}
          </div>
        </div>

        <h2 className="font-sans text-xl md:text-2xl font-bold leading-tight text-charcoal mb-3 group-hover:text-black transition-colors text-balance">
          <a href={article.url} target="_blank" rel="noopener noreferrer" className="hover:underline decoration-stone-300 underline-offset-[6px] decoration-2">
            {article.title}
          </a>
        </h2>

        <div className="flex items-center text-xs text-stone-500 font-medium mt-3 pt-3 border-t border-stone-200/50">
          <span className="text-stone-800 mr-2 uppercase tracking-wider text-[10px]">{article.author}</span>
          <span className="mr-2 text-stone-300">•</span>
          <span className="italic font-sans truncate">{article.source}</span>
        </div>
      </div>

      {/* Summary - Integrated */}
      <div className="px-5 pb-5 md:px-6 md:pb-6 flex-grow">
        <div className="space-y-2">
          {article.summary.map((paragraph, idx) => (
            <p key={idx} className="text-stone-600 leading-relaxed font-sans text-sm">
              {paragraph}
            </p>
          ))}
        </div>
      </div>

      {/* Insights & Tips Grid - Compacted */}
      <div className="grid grid-cols-1 md:grid-cols-2 border-t border-stone-200/60 text-xs bg-white/50">
        {/* Insights Section */}
        <div className="p-4 md:p-5 border-b md:border-b-0 md:border-r border-stone-200/60"> 
          <div className="flex items-center mb-2 text-amber-700 font-extrabold uppercase tracking-widest text-[10px]">
            <Lightbulb className="w-3.5 h-3.5 mr-2 text-amber-500 fill-amber-500/20" />
            Core Insights
          </div>
          <ul className="space-y-2">
            {article.insights.map((insight, idx) => (
              <li key={idx} className="flex items-start text-stone-700 leading-normal">
                <span className="mr-2 mt-1.5 w-1 h-1 bg-amber-400 rounded-full flex-shrink-0" />
                <span>{insight}</span>
              </li>
            ))}
          </ul>
        </div>

        {/* Action Plan Section */}
        <div className="p-4 md:p-5">
          <div className="flex items-center mb-2 text-charcoal font-extrabold uppercase tracking-widest text-[10px]">
            <Zap className="w-3.5 h-3.5 mr-2 text-stone-400 fill-stone-200" />
            Action Plan
          </div>
          <ul className="space-y-2">
            {article.application_tips.map((tip, idx) => (
              <li key={idx} className="flex items-start text-stone-600 leading-normal">
                <span className="mr-2 mt-1.5 w-1 h-1 bg-stone-300 rounded-full flex-shrink-0" />
                <span>{tip}</span>
              </li>
            ))}
          </ul>
        </div>
      </div>

      {/* Footer */}
      {(onToggleSave || onRate) && (
        <div className="px-4 py-3 md:px-5 md:py-3 border-t border-stone-200/60 bg-white/60 flex justify-between items-center text-stone-400 backdrop-blur-sm">
          <div className="flex space-x-2">
            {onRate && (
              <>
                <button 
                  onClick={() => onRate(article, rating === 'up' ? null : 'up')}
                  className={`p-1.5 rounded-full transition-all duration-300 active:scale-90 ${rating === 'up' ? 'text-green-600 bg-green-50 scale-110 shadow-sm ring-1 ring-green-100' : 'hover:bg-stone-100 hover:text-stone-600'}`}
                  title="More like this"
                >
                  <ThumbsUp className={`w-3.5 h-3.5 ${rating === 'up' ? 'fill-current' : ''}`} />
                </button>
                <button 
                  onClick={() => onRate(article, rating === 'down' ? null : 'down')}
                  className={`p-1.5 rounded-full transition-all duration-300 active:scale-90 ${rating === 'down' ? 'text-red-600 bg-red-50 scale-110 shadow-sm ring-1 ring-red-100' : 'hover:bg-stone-100 hover:text-stone-600'}`}
                  title="Less like this"
                >
                  <ThumbsDown className={`w-3.5 h-3.5 ${rating === 'down' ? 'fill-current' : ''}`} />
                </button>
              </>
            )}
          </div>

          <div className="flex items-center space-x-2 md:space-x-3">
             {article.tweet_draft && (
                <button
                    onClick={handleCopyTweet}
                    className={`flex items-center space-x-2 px-3 py-1 rounded-full text-[10px] font-bold tracking-widest transition-all duration-300 active:scale-95 border ${copied ? 'text-blue-600 bg-blue-50 border-blue-100' : 'text-stone-400 border-transparent hover:text-blue-500 hover:bg-blue-50/50 hover:border-blue-100'}`}
                    title="Copy Tweet to Clipboard"
                >
                    {copied ? <Check className="w-3 h-3" /> : <Twitter className="w-3 h-3" />}
                    <span className="uppercase hidden sm:inline">{copied ? 'Copied' : 'Tweet'}</span>
