               </div>
             )}

             {view === 'history' && (
                <div className="space-y-4 md:space-y-6 pb-20">
                  {history.length === 0 ? <p className="text-center py-20 text-stone-400">History is empty.</p> : 
                    history.map(item => (
                      <div 
