interface ArticleCardProps {
  article: Article;
  isSaved?: boolean;
  rating?: 'up' | 'down' | null;
  onToggleSave?: (article: Article) => void;
  onRate?: (article: Article, rating: 'up' | 'down' | null) => void;
}

