          </div>

          {/* Analyze Button - Expands when valid */}
          <div className={`transition-all duration-500 ease-out ${isValidUrl && !isLoading ? 'w-auto opacity-100 translate-x-0' : 'w-0 opacity-0 translate-x-4 overflow-hidden'}`}>
            <button
                type="submit"
