                className="flex items-center gap-2 px-6 py-3 rounded-full bg-charcoal text-white font-bold text-sm shadow-md hover:shadow-lg hover:scale-105 active:scale-95 transition-all whitespace-nowrap group/btn"
            >
                <span>Analyze</span>
                <ArrowRight className="w-4 h-4 group-hover/btn:translate-x-1 transition-transform" />
            </button>
          </div>

           {/* Empty State Helper (Sparkle) */}
           <div className={`
              pointer-events-none transition-all duration-500 text-stone-300 mr-4 flex items-center
              ${!isValidUrl && !isLoading ? 'opacity-100 translate-x-0 scale-100' : 'opacity-0 translate-x-4 scale-50 absolute'}
           `}>
              <Sparkles className="w-5 h-5 opacity-40" />
           </div>

        </div>
      </form>

      {/* Decorative 'Glow' behind */}
      <div className={`
        absolute -inset-4 bg-gradient-to-r from-blue-500/10 via-purple-500/10 to-amber-500/10 rounded-[100%] blur-2xl transition-opacity duration-1000 -z-10
        ${isFocused ? 'opacity-100' : 'opacity-0'}
      `} />

      {/* Contextual Helper Text */}
      <div className={`
          absolute -bottom-8 left-0 right-0 text-center transition-all duration-500 delay-100
