                                 {topic}
                              </span>
                            ))}
                          </div>
                        )}

                        {item.type === 'url' && (
                            <div className="text-sm text-stone-500 line-clamp-1 font-sans">
                                {item.articles[0]?.summary?.[0] || "No summary available."}
                            </div>
                        )}
                      </div>
                    ))
                  }
                </div>
             )}
           </div>
        )}
      </main>

      <footer className="mt-12 md:mt-24 pb-12 text-center text-stone-400 group/footer px-4">
        <div className="max-w-2xl mx-auto border-t border-stone-200/50 pt-12 relative">
          <Quote className="w-5 h-5 opacity-40 text-stone-400 mx-auto mb-6" />
          <p className="font-sans text-lg md:text-xl text-stone-600 mb-3">"{currentQuote.text}"</p>
          <p className="text-xs font-bold uppercase tracking-widest">— {currentQuote.author}</p>
          <button onClick={handleNewQuote} className="mt-6 p-2 rounded-full text-stone-300 hover:text-stone-500 opacity-0 group-hover/footer:opacity-100 transition-all">
            <Shuffle className="w-4 h-4" />
          </button>
        </div>
      </footer>
    </div>
  );
}

export default function App() {
  return (
    <SimpleErrorBoundary>
      <AppContent />
    </SimpleErrorBoundary>
  );
}

import React from 'react';
import { DigestConfig, ExperienceLevel, Topic, DateRange } from '../types.ts';
import { AVAILABLE_TOPICS } from '../constants.ts';
import { RefreshCw, Clock, Signal } from 'lucide-react';

interface DigestConfiguratorProps {
  config: DigestConfig;
  setConfig: React.Dispatch<React.SetStateAction<DigestConfig>>;
  onGenerate: () => void;
  isLoading: boolean;
}

const DigestConfigurator: React.FC<DigestConfiguratorProps> = ({ config, setConfig, onGenerate, isLoading }) => {

  const toggleTopic = (topic: Topic) => {
    setConfig(prev => {
      // If selecting Random, clear others and just set Random
      if (topic === 'Random/Surprise Me') {
        return { ...prev, topics: ['Random/Surprise Me'] };
      }

      // Filter out Random from the existing list (since we are interacting with specific topics)
      const currentTopicsWithoutRandom = prev.topics.filter(t => t !== 'Random/Surprise Me');

      if (prev.topics.includes(topic)) {
        // We are deselecting a topic
        const remaining = currentTopicsWithoutRandom.filter(t => t !== topic);

        // If nothing is left, default back to Random/Surprise Me
        if (remaining.length === 0) {
          return { ...prev, topics: ['Random/Surprise Me'] };
        }

        return { ...prev, topics: remaining };
      } else {
        // We are adding a topic
        return { ...prev, topics: [...currentTopicsWithoutRandom, topic] };
      }
    });
  };

  const handleLevelChange = (level: ExperienceLevel) => {
    setConfig(prev => ({ ...prev, level }));
  };

  const handleDateRangeChange = (dateRange: DateRange) => {
    setConfig(prev => ({ ...prev, dateRange }));
  };

  const dateRanges: DateRange[] = ['Last 24 Hours', 'Last Week', 'Last Month', 'Last 6 Months', 'Any Time'];

  const levels: { id: ExperienceLevel; title: string; subtitle: string }[] = [
    { id: 'Junior', title: 'Junior', subtitle: 'Foundations & Core Concepts' },
    { id: 'Mid-Level', title: 'Mid-Level', subtitle: 'Execution & Detailed Analysis' },
    { id: 'Senior', title: 'Senior', subtitle: 'Strategy, Systems & Leadership' },
  ];

  const displayTopics = AVAILABLE_TOPICS;

  return (
    <div className="bg-white rounded-3xl p-6 md:p-8 shadow-[0_8px_30px_rgba(0,0,0,0.02)] border border-stone-100 max-w-4xl mx-auto mb-12 relative overflow-hidden">
      <div className="flex flex-col md:flex-row gap-8 md:gap-10">

        {/* Left Column: Level (Luxe Pop) */}
        <div className="flex-shrink-0 md:w-1/3 space-y-4">

          <div className="flex items-center text-[10px] font-extrabold uppercase tracking-widest text-stone-400 px-1 mb-1">
             <Signal className="w-3 h-3 mr-1.5" />
             Experience Level
          </div>

          {/* Level Buttons - Stacked/Grid hybrid */}
          <div className="flex flex-col gap-2">
            {levels.map((lvl) => {
              const isSelected = config.level === lvl.id;

              return (
                <button
                  key={lvl.id}
                  onClick={() => handleLevelChange(lvl.id)}
                  className={`
                    w-full flex items-center justify-between px-5 py-3.5 rounded-2xl transition-all duration-300 ease-out group relative overflow-hidden
                    ${isSelected 
                      ? 'bg-charcoal text-white shadow-xl shadow-charcoal/10 scale-[1.02] z-10' 
                      : 'bg-stone-50/50 text-stone-400 hover:bg-white hover:text-stone-800 hover:shadow-md'
                    }
                  `}
                >
                  <span className={`font-sans font-bold text-sm tracking-wide ${isSelected ? 'text-white' : 'text-stone-500 group-hover:text-charcoal'}`}>
                    {lvl.title}
                  </span>
                  {isSelected && <div className="w-1.5 h-1.5 rounded-full bg-white shadow-sm" />}
                </button>
              );
            })}
          </div>

          {/* Dynamic Description - Clean text */}
          <div className="px-1 pt-2">
             <p key={config.level} className="text-xs text-stone-500 font-medium leading-relaxed animate-in fade-in slide-in-from-top-1 duration-300">
               {levels.find(l => l.id === config.level)?.subtitle}
             </p>
          </div>
        </div>

        {/* Right Column: Topics & Timeframe */}
        <div className="flex-grow flex flex-col pt-6 md:pt-0 border-t border-stone-100 md:border-t-0 md:border-l md:pl-10">

           {/* Topics Section */}
           <div className="mb-8">
             <div className="flex items-center text-[10px] font-extrabold uppercase tracking-widest text-stone-400 mb-3 pl-1">
                Topics
              </div>

              {/* Minimal Pills Layout */}
              <div className="flex flex-wrap gap-2">
                {displayTopics.map((topic) => {
                  const isSelected = config.topics.includes(topic);
                  return (
                    <button
                      key={topic}
                      onClick={() => toggleTopic(topic)}
                      className={`
                        px-4 py-2 rounded-full text-xs font-bold transition-all duration-200 active:scale-95 border
                        ${isSelected
                          ? 'bg-charcoal border-charcoal text-white shadow-lg shadow-charcoal/10 transform scale-105'
                          : 'bg-white border-stone-200 text-stone-500 hover:border-stone-300 hover:text-charcoal hover:shadow-sm'
                        }
                      `}
                    >
                      {topic}
                    </button>
                  );
                })}
              </div>
           </div>

          {/* Timeframe Section */}
          <div className="mt-auto">
             <div className="flex items-center text-[10px] font-extrabold uppercase tracking-widest text-stone-400 mb-3 pl-1">
                <Clock className="w-3 h-3 mr-1.5" />
                Timeframe
             </div>

             <div className="flex flex-wrap gap-2 mb-6">
                {dateRanges.map((range) => {
                  const isSelected = config.dateRange === range;

                  let label: string = range;
                  if (range === 'Last 24 Hours') label = '24h';
                  else if (range === 'Last Week') label = '1 Week';
                  else if (range === 'Last Month') label = '1 Month';
                  else if (range === 'Last 6 Months') label = '6 Months';
                  else if (range === 'Any Time') label = 'All';

                  return (
                    <button
                      key={range}
                      onClick={() => handleDateRangeChange(range)}
                      className={`
                        min-w-[60px] flex-1 px-3 py-2.5 rounded-xl text-xs font-bold tracking-wide transition-all duration-200 border text-center
                        ${isSelected 
                          ? 'bg-charcoal text-white border-charcoal shadow-lg shadow-charcoal/10 transform scale-105 z-10' 
                          : 'bg-white text-stone-500 border-stone-200 hover:border-stone-300 hover:text-charcoal hover:bg-stone-50'
                        }
                      `}
                    >
                      {label}
                    </button>
                  );
                })}
             </div>

            {/* Generate Button */}
            <button
                onClick={onGenerate}
                disabled={isLoading || config.topics.length === 0}
                className={`
                w-full group relative flex items-center justify-center px-8 py-4 rounded-full font-sans font-bold text-lg shadow-2xl transition-all duration-300
                ${isLoading 
                    ? 'bg-stone-100 text-stone-400 cursor-not-allowed translate-y-0 shadow-none' 
                    : 'bg-charcoal text-white hover:bg-black hover:-translate-y-1 hover:shadow-charcoal/30 active:translate-y-0 active:scale-95'
                }
                `}
            >
                {isLoading ? (
                <span className="flex items-center">
                    <RefreshCw className="mr-2 w-5 h-5 animate-spin" />
                    Synthesizing...
                </span>
                ) : (
                <>
                    <span className="relative z-10">Generate Briefing</span>
                    <RefreshCw className="ml-3 w-5 h-5 opacity-70 group-hover:opacity-100 transition-all group-hover:rotate-180" />
                </>
                )}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DigestConfigurator;

