              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-8 pb-20">
                {articles.map(article => (
                  <ArticleCard 
                    key={article.url} 
                    article={article} 
                    isSaved={savedArticles.some(a => a.url === article.url)}
                    rating={likedArticles.some(a => a.url === article.url) ? 'up' : dislikedArticles.some(a => a.url === article.url) ? 'down' : null}
                    onToggleSave={handleToggleSave}
                    onRate={handleRate}
                  />
                ))}
              </div>
            )}
          </div>
        )}

        {(view === 'saved' || view === 'history') && (
           <div className="animate-in fade-in duration-300 max-w-4xl mx-auto">

             {view === 'saved' && (
               <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-8 pb-20">
                 {savedArticles.length === 0 ? <p className="col-span-full text-center py-20 text-stone-400">No saved articles yet.</p> : 
                   savedArticles.map(article => (
                     <ArticleCard key={article.url} article={article} isSaved={true} onToggleSave={handleToggleSave} onRate={handleRate} />
                   ))
                 }
               </div>
             )}

             {view === 'history' && (
                <div className="space-y-4 md:space-y-6 pb-20">
                  {history.length === 0 ? <p className="text-center py-20 text-stone-400">History is empty.</p> : 
                    history.map(item => (
                      <div 
                        key={item.id} 
                        onClick={() => {setArticles(item.articles); setView('result');}} 
                        className="bg-white p-5 md:p-6 rounded-2xl border border-stone-200 hover:shadow-[0_8px_30px_rgb(0,0,0,0.04)] hover:border-stone-300 cursor-pointer transition-all group relative overflow-hidden"
                      >
                        {/* Hover Indicator Line */}
                        <div className="absolute left-0 top-0 bottom-0 w-1 bg-charcoal transform -translate-x-full group-hover:translate-x-0 transition-transform duration-300" />

                        <div className="flex justify-between items-start mb-3">
                           <div className="flex items-center gap-2">
                              <span className="text-[10px] font-bold text-stone-400 uppercase tracking-widest bg-stone-50 px-2 py-1 rounded-md border border-stone-100">
                                {new Date(item.timestamp).toLocaleDateString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
                              </span>
                              {item.type === 'feed' && (
                                 <span className="text-[10px] font-bold text-stone-500 bg-white px-2 py-1 rounded-md border border-stone-200 uppercase tracking-widest flex items-center gap-1">
                                    <Filter className="w-3 h-3" />
                                    {item.config.level}
                                 </span>
                              )}
                           </div>
                           <div className="p-2 bg-stone-50 rounded-full group-hover:bg-charcoal group-hover:text-white transition-colors">
                              <ChevronRight className="w-4 h-4" />
                           </div>
                        </div>

                        <h3 className="font-sans text-xl md:text-2xl font-bold text-charcoal mb-4 group-hover:text-black transition-colors leading-tight">
                          {item.type === 'url' ? (
                            <span className="flex items-center gap-2">
                               <Link className="w-5 h-5 text-stone-400 flex-shrink-0" />
                               {item.articles[0]?.title || "URL Analysis"}
                            </span>
                          ) : (
                            `${item.articles.length} Articles Briefing`
                          )}
                        </h3>

                        {item.type === 'feed' && item.config.topics && (
                          <div className="flex flex-wrap gap-2 mt-auto">
                            {item.config.topics.map((topic, i) => (
                              <span key={i} className="inline-flex items-center px-2 py-1 rounded-md text-[11px] font-medium bg-stone-100 text-stone-600 border border-stone-200">
                                 <Tag className="w-3 h-3 mr-1 opacity-50" />
                                 {topic}
                              </span>
                            ))}
                          </div>
                        )}

                        {item.type === 'url' && (
                            <div className="text-sm text-stone-500 line-clamp-1 font-sans">
                                {item.articles[0]?.summary?.[0] || "No summary available."}
                            </div>
                        )}
                      </div>
                    ))
                  }
                </div>
             )}
           </div>
        )}
      </main>

      <footer className="mt-12 md:mt-24 pb-12 text-center text-stone-400 group/footer px-4">
        <div className="max-w-2xl mx-auto border-t border-stone-200/50 pt-12 relative">
          <Quote className="w-5 h-5 opacity-40 text-stone-400 mx-auto mb-6" />
          <p className="font-sans text-lg md:text-xl text-stone-600 mb-3">"{currentQuote.text}"</p>
          <p className="text-xs font-bold uppercase tracking-widest">— {currentQuote.author}</p>
          <button onClick={handleNewQuote} className="mt-6 p-2 rounded-full text-stone-300 hover:text-stone-500 opacity-0 group-hover/footer:opacity-100 transition-all">
            <Shuffle className="w-4 h-4" />
          </button>
        </div>
      </footer>
    </div>
  );
}

export default function App() {
  return (
    <SimpleErrorBoundary>
      <AppContent />
    </SimpleErrorBoundary>
  );
}

import React from 'react';
import { DigestConfig, ExperienceLevel, Topic, DateRange } from '../types.ts';
import { AVAILABLE_TOPICS } from '../constants.ts';
import { RefreshCw, Clock, Signal } from 'lucide-react';

interface DigestConfiguratorProps {
  config: DigestConfig;
  setConfig: React.Dispatch<React.SetStateAction<DigestConfig>>;
  onGenerate: () => void;
  isLoading: boolean;
}

const DigestConfigurator: React.FC<DigestConfiguratorProps> = ({ config, setConfig, onGenerate, isLoading }) => {

  const toggleTopic = (topic: Topic) => {
    setConfig(prev => {
      // If selecting Random, clear others and just set Random
      if (topic === 'Random/Surprise Me') {
        return { ...prev, topics: ['Random/Surprise Me'] };
      }

      // Filter out Random from the existing list (since we are interacting with specific topics)
      const currentTopicsWithoutRandom = prev.topics.filter(t => t !== 'Random/Surprise Me');

      if (prev.topics.includes(topic)) {
        // We are deselecting a topic
        const remaining = currentTopicsWithoutRandom.filter(t => t !== topic);

        // If nothing is left, default back to Random/Surprise Me
        if (remaining.length === 0) {
          return { ...prev, topics: ['Random/Surprise Me'] };
        }

        return { ...prev, topics: remaining };
      } else {
        // We are adding a topic
        return { ...prev, topics: [...currentTopicsWithoutRandom, topic] };
      }
    });
  };

  const handleLevelChange = (level: ExperienceLevel) => {
    setConfig(prev => ({ ...prev, level }));
  };

  const handleDateRangeChange = (dateRange: DateRange) => {
    setConfig(prev => ({ ...prev, dateRange }));
  };

  const dateRanges: DateRange[] = ['Last 24 Hours', 'Last Week', 'Last Month', 'Last 6 Months', 'Any Time'];

  const levels: { id: ExperienceLevel; title: string; subtitle: string }[] = [
    { id: 'Junior', title: 'Junior', subtitle: 'Foundations & Core Concepts' },
    { id: 'Mid-Level', title: 'Mid-Level', subtitle: 'Execution & Detailed Analysis' },
    { id: 'Senior', title: 'Senior', subtitle: 'Strategy, Systems & Leadership' },
  ];

  const displayTopics = AVAILABLE_TOPICS;

  return (
    <div className="bg-white rounded-3xl p-6 md:p-8 shadow-[0_8px_30px_rgba(0,0,0,0.02)] border border-stone-100 max-w-4xl mx-auto mb-12 relative overflow-hidden">
      <div className="flex flex-col md:flex-row gap-8 md:gap-10">

        {/* Left Column: Level (Luxe Pop) */}
        <div className="flex-shrink-0 md:w-1/3 space-y-4">

          <div className="flex items-center text-[10px] font-extrabold uppercase tracking-widest text-stone-400 px-1 mb-1">
             <Signal className="w-3 h-3 mr-1.5" />
             Experience Level
          </div>

          {/* Level Buttons - Stacked/Grid hybrid */}
          <div className="flex flex-col gap-2">
            {levels.map((lvl) => {
              const isSelected = config.level === lvl.id;

              return (
                <button
                  key={lvl.id}
                  onClick={() => handleLevelChange(lvl.id)}
                  className={`
                    w-full flex items-center justify-between px-5 py-3.5 rounded-2xl transition-all duration-300 ease-out group relative overflow-hidden
                    ${isSelected 
                      ? 'bg-charcoal text-white shadow-xl shadow-charcoal/10 scale-[1.02] z-10' 
                      : 'bg-stone-50/50 text-stone-400 hover:bg-white hover:text-stone-800 hover:shadow-md'
                    }
                  `}
                >
                  <span className={`font-sans font-bold text-sm tracking-wide ${isSelected ? 'text-white' : 'text-stone-500 group-hover:text-charcoal'}`}>
                    {lvl.title}
                  </span>
                  {isSelected && <div className="w-1.5 h-1.5 rounded-full bg-white shadow-sm" />}
                </button>
              );
            })}
          </div>

          {/* Dynamic Description - Clean text */}
          <div className="px-1 pt-2">
             <p key={config.level} className="text-xs text-stone-500 font-medium leading-relaxed animate-in fade-in slide-in-from-top-1 duration-300">
               {levels.find(l => l.id === config.level)?.subtitle}
             </p>
          </div>
        </div>

        {/* Right Column: Topics & Timeframe */}
        <div className="flex-grow flex flex-col pt-6 md:pt-0 border-t border-stone-100 md:border-t-0 md:border-l md:pl-10">

           {/* Topics Section */}
           <div className="mb-8">
             <div className="flex items-center text-[10px] font-extrabold uppercase tracking-widest text-stone-400 mb-3 pl-1">
                Topics
              </div>

              {/* Minimal Pills Layout */}
              <div className="flex flex-wrap gap-2">
                {displayTopics.map((topic) => {
                  const isSelected = config.topics.includes(topic);
                  return (
                    <button
                      key={topic}
                      onClick={() => toggleTopic(topic)}
                      className={`
                        px-4 py-2 rounded-full text-xs font-bold transition-all duration-200 active:scale-95 border
                        ${isSelected
                          ? 'bg-charcoal border-charcoal text-white shadow-lg shadow-charcoal/10 transform scale-105'
                          : 'bg-white border-stone-200 text-stone-500 hover:border-stone-300 hover:text-charcoal hover:shadow-sm'
                        }
                      `}
                    >
                      {topic}
                    </button>
                  );
                })}
              </div>
           </div>

          {/* Timeframe Section */}
          <div className="mt-auto">
             <div className="flex items-center text-[10px] font-extrabold uppercase tracking-widest text-stone-400 mb-3 pl-1">
                <Clock className="w-3 h-3 mr-1.5" />
                Timeframe
             </div>

             <div className="flex flex-wrap gap-2 mb-6">
                {dateRanges.map((range) => {
                  const isSelected = config.dateRange === range;

                  let label: string = range;
                  if (range === 'Last 24 Hours') label = '24h';
                  else if (range === 'Last Week') label = '1 Week';
                  else if (range === 'Last Month') label = '1 Month';
                  else if (range === 'Last 6 Months') label = '6 Months';
                  else if (range === 'Any Time') label = 'All';

                  return (
                    <button
                      key={range}
                      onClick={() => handleDateRangeChange(range)}
                      className={`
                        min-w-[60px] flex-1 px-3 py-2.5 rounded-xl text-xs font-bold tracking-wide transition-all duration-200 border text-center
                        ${isSelected 
                          ? 'bg-charcoal text-white border-charcoal shadow-lg shadow-charcoal/10 transform scale-105 z-10' 
                          : 'bg-white text-stone-500 border-stone-200 hover:border-stone-300 hover:text-charcoal hover:bg-stone-50'
                        }
                      `}
                    >
                      {label}
                    </button>
                  );
                })}
             </div>

            {/* Generate Button - Minimal Version */}
            <button
                onClick={onGenerate}
                disabled={isLoading || config.topics.length === 0}
                className={`
                w-full group relative flex items-center justify-center px-8 py-4 rounded-full font-sans font-bold text-lg transition-all duration-500 ease-out border border-transparent
                ${isLoading 
                    ? 'bg-stone-100 text-stone-400 cursor-not-allowed' 
                    : 'bg-charcoal text-white hover:shadow-[0_0_25px_rgba(28,28,28,0.4)] active:scale-[0.98]'
                }
                `}
            >
                {isLoading ? (
                <span className="flex items-center animate-pulse">
                    Synthesizing...
                </span>
                ) : (
                <span>Generate Briefing</span>
                )}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DigestConfigurator;

import React, { useState, useRef } from 'react';
import { Search, ArrowRight, Link, Video, X, Loader2, Sparkles, Youtube, Globe, FileSearch } from 'lucide-react';

interface UrlAnalyzerProps {
  onAnalyze: (url: string) => void;
  isLoading: boolean;
}

const UrlAnalyzer: React.FC<UrlAnalyzerProps> = ({ onAnalyze, isLoading }) => {
  const [url, setUrl] = useState('');
  const [isFocused, setIsFocused] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (isValidUrl) {
      onAnalyze(url);
    }
  };

  const handleClear = () => {
    setUrl('');
    inputRef.current?.focus();
  };

  // Simple validation check
  const isValidUrl = url.trim().length > 3 && (url.includes('.') || url.includes('localhost'));

  // Detect if it's likely a video
  const isVideo = url.toLowerCase().includes('youtube') || url.toLowerCase().includes('vimeo') || url.toLowerCase().includes('youtu.be');

  return (
    <div className="w-full max-w-2xl mx-auto mb-20 relative z-20 px-4 md:px-0">

      {/* Minimal Header */}
      <div className="text-center mb-6">
        <h3 className="font-display text-2xl font-bold text-charcoal mb-2">Deep Dive</h3>
        <p className="text-sm text-stone-500 font-medium">Analyze any article or video URL for insights.</p>
      </div>

      {/* Minimal Input Form */}
      <form 
        onSubmit={handleSubmit}
        className={`
          relative flex items-center p-2 bg-white rounded-full border shadow-sm transition-all duration-300
          ${isFocused 
            ? 'border-charcoal ring-2 ring-stone-100 shadow-md transform scale-[1.01]' 
            : 'border-stone-200 hover:border-stone-300'
          }
        `}
        onClick={() => inputRef.current?.focus()}
      >
        {/* Leading Icon */}
        <div className="pl-4 pr-3 text-stone-400">
            {isLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : 
            isVideo ? <Youtube className="w-5 h-5 text-red-600" /> : 
            <Link className="w-5 h-5" />
            }
        </div>

        {/* Main Input Field */}
        <input
          ref={inputRef}
          type="text"
          value={url}
          onChange={(e) => setUrl(e.target.value)}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          placeholder="Paste URL..."
          className="flex-grow bg-transparent border-none outline-none text-base text-charcoal placeholder:text-stone-400 font-sans h-10 w-full"
          disabled={isLoading}
          autoComplete="off"
        />

        {/* Actions Right Side */}
        <div className="flex items-center gap-2 pr-1">
          {/* Clear Button */}
          {url.length > 0 && !isLoading && (
              <button 
                type="button"
                onClick={(e) => { e.stopPropagation(); handleClear(); }} 
                className="p-2 rounded-full hover:bg-stone-100 text-stone-400 hover:text-charcoal transition-colors"
              >
                <X className="w-4 h-4" />
              </button>
          )}

          {/* Analyze Button */}
          <button
              type="submit"
              disabled={!isValidUrl || isLoading}
              className={`
                flex items-center justify-center w-10 h-10 rounded-full transition-all duration-300
                ${isValidUrl && !isLoading
                  ? 'bg-charcoal text-white shadow-md hover:scale-110 active:scale-95'
                  : 'bg-stone-100 text-stone-300 cursor-not-allowed'
                }
              `}
          >
              <ArrowRight className="w-4 h-4" />
          </button>
        </div>
      </form>
    </div>
  );
};

export default UrlAnalyzer;

