import React from 'react';
import { DigestConfig, ExperienceLevel, Topic, DateRange } from '../types.ts';
import { AVAILABLE_TOPICS } from '../constants.ts';
import { RefreshCw, Clock, Signal, Layers } from 'lucide-react';

interface DigestConfiguratorProps {
  config: DigestConfig;
  setConfig: React.Dispatch<React.SetStateAction<DigestConfig>>;
  onGenerate: () => void;
  isLoading: boolean;
}

const DigestConfigurator: React.FC<DigestConfiguratorProps> = ({ config, setConfig, onGenerate, isLoading }) => {

  const toggleTopic = (topic: Topic) => {
    setConfig(prev => {
      // If selecting Random, clear others and just set Random
      if (topic === 'Random/Surprise Me') {
        return { ...prev, topics: ['Random/Surprise Me'] };
      }

      // Filter out Random from the existing list (since we are interacting with specific topics)
      const currentTopicsWithoutRandom = prev.topics.filter(t => t !== 'Random/Surprise Me');

      if (prev.topics.includes(topic)) {
        // We are deselecting a topic
        const remaining = currentTopicsWithoutRandom.filter(t => t !== topic);

        // If nothing is left, default back to Random/Surprise Me
        if (remaining.length === 0) {
          return { ...prev, topics: ['Random/Surprise Me'] };
        }

        return { ...prev, topics: remaining };
      } else {
        // We are adding a topic
        return { ...prev, topics: [...currentTopicsWithoutRandom, topic] };
      }
    });
  };

  const handleLevelChange = (level: ExperienceLevel) => {
    setConfig(prev => ({ ...prev, level }));
  };

  const handleDateRangeChange = (dateRange: DateRange) => {
    setConfig(prev => ({ ...prev, dateRange }));
  };

  const dateRanges: DateRange[] = ['Last 24 Hours', 'Last Week', 'Last Month', 'Last 6 Months', 'Any Time'];

  const levels: { id: ExperienceLevel; title: string; subtitle: string }[] = [
    { id: 'Junior', title: 'Junior', subtitle: 'Foundations & Concepts' },
    { id: 'Mid-Level', title: 'Mid-Level', subtitle: 'Execution & Strategy' },
    { id: 'Senior', title: 'Senior', subtitle: 'Systems & Leadership' },
  ];

  const displayTopics = AVAILABLE_TOPICS;

  return (
    <div className="bg-white rounded-3xl p-6 md:p-8 shadow-[0_8px_30px_rgba(0,0,0,0.02)] border border-stone-100 max-w-xl mx-auto mb-12 relative overflow-hidden">

      <div className="space-y-8">

        {/* Experience Level Section - Tab Style */}
        <div>
          <div className="flex items-center text-[10px] font-extrabold uppercase tracking-widest text-stone-400 px-1 mb-3">
             <Signal className="w-3 h-3 mr-1.5" />
             Experience Level
          </div>

          <div className="bg-stone-100/70 p-1.5 rounded-2xl flex relative">
            {levels.map((lvl) => {
              const isSelected = config.level === lvl.id;
              return (
                <button
                  key={lvl.id}
                  onClick={() => handleLevelChange(lvl.id)}
                  className={`
                    flex-1 py-2.5 rounded-xl text-xs font-semibold transition-all duration-300 relative z-10
                    ${isSelected 
                      ? 'bg-white text-charcoal shadow-sm ring-1 ring-black/5' 
                      : 'text-stone-400 hover:text-stone-600'
                    }
                  `}
                >
                  {lvl.title}
                </button>
              );
            })}
          </div>

          {/* Subtle Subtitle Display */}
          <div className="mt-2 px-1 text-center h-4">
             <p className="text-[10px] text-stone-400 font-medium animate-in fade-in duration-300">
               {levels.find(l => l.id === config.level)?.subtitle}
             </p>
          </div>
        </div>

        {/* Topics Section - Lighter Pills */}
        <div>
           <div className="flex items-center text-[10px] font-extrabold uppercase tracking-widest text-stone-400 px-1 mb-3">
             <Layers className="w-3 h-3 mr-1.5" />
             Topics
           </div>

           <div className="flex flex-wrap gap-2 justify-center md:justify-start">
              {displayTopics.map((topic) => {
                const isSelected = config.topics.includes(topic);
                return (
                  <button
                    key={topic}
                    onClick={() => toggleTopic(topic)}
                    className={`
                      px-3.5 py-1.5 rounded-full text-xs font-medium transition-all duration-200 active:scale-95 border
                      ${isSelected
                        ? 'bg-stone-100 border-stone-200 text-charcoal'
                        : 'bg-white border-transparent text-stone-400 hover:text-stone-600 hover:bg-stone-50'
                      }
                    `}
                  >
                    {topic}
                  </button>
                );
              })}
           </div>
        </div>

        {/* Timeframe Section - Lighter Pills */}
        <div>
           <div className="flex items-center text-[10px] font-extrabold uppercase tracking-widest text-stone-400 px-1 mb-3">
              <Clock className="w-3 h-3 mr-1.5" />
              Timeframe
           </div>

           <div className="flex flex-wrap gap-2 justify-center md:justify-start">
              {dateRanges.map((range) => {
                const isSelected = config.dateRange === range;

                let label: string = range;
                if (range === 'Last 24 Hours') label = '24h';
                else if (range === 'Last Week') label = '1 Week';
                else if (range === 'Last Month') label = '1 Month';
                else if (range === 'Last 6 Months') label = '6 Months';
                else if (range === 'Any Time') label = 'All';

                return (
                  <button
                    key={range}
                    onClick={() => handleDateRangeChange(range)}
                    className={`
                      px-3.5 py-1.5 rounded-full text-xs font-medium transition-all duration-200 active:scale-95 border
                      ${isSelected 
                        ? 'bg-stone-100 text-charcoal border-stone-200' 
                        : 'bg-white text-stone-400 border-transparent hover:text-stone-600 hover:bg-stone-50'
                      }
                    `}
                  >
                    {label}
                  </button>
                );
              })}
           </div>
        </div>

        {/* Generate Button */}
        <div className="pt-2">
            <button
                onClick={onGenerate}
                disabled={isLoading || config.topics.length === 0}
                className={`
                w-full group relative flex items-center justify-center px-8 py-4 rounded-full font-sans font-bold text-lg transition-all duration-500 ease-out border border-transparent
                ${isLoading 
                    ? 'bg-stone-100 text-stone-400 cursor-not-allowed' 
                    : 'bg-charcoal text-white hover:shadow-[0_0_25px_rgba(28,28,28,0.4)] active:scale-[0.98]'
                }
                `}
            >
                {isLoading ? (
                <span className="flex items-center animate-pulse">
                    Synthesizing...
                </span>
                ) : (
                <span>Generate Briefing</span>
                )}
            </button>
        </div>
      </div>
    </div>
  );
};

export default DigestConfigurator;

import React, { useState, useEffect, ErrorInfo, ReactNode, Component } from 'react';
import { DigestConfig, Article, DigestHistoryItem, UserPreferences } from './types.ts';
import DigestConfigurator from './components/DigestConfigurator.tsx';
import ArticleCard from './components/ArticleCard.tsx';
import UrlAnalyzer from './components/UrlAnalyzer.tsx';
import SkeletonLoader from './components/SkeletonLoader.tsx';
import { History, Bookmark, Home, AlertTriangle, Link, Tag, ChevronRight, Filter } from 'lucide-react';
import { FALLBACK_ARTICLES } from './constants.ts';

// --- Error Boundary Component ---
interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

// Fixed: Explicitly extend Component to ensure props are typed correctly
class SimpleErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  public state: ErrorBoundaryState = {
    hasError: false,
    error: null
  };

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("ErrorBoundary caught an error", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="p-8 text-center min-h-screen flex flex-col items-center justify-center bg-[#FEFBF6]">
          <h2 className="text-2xl font-bold text-red-600 mb-2">Something went wrong.</h2>
          <p className="text-stone-600 mb-4">Please try refreshing the page.</p>
          <pre className="text-xs bg-white border border-stone-200 p-4 rounded text-left overflow-auto max-w-lg w-full">
            {this.state.error?.toString()}
          </pre>
          <button 
            onClick={() => window.location.reload()}
            className="mt-6 px-6 py-2 bg-charcoal text-white rounded-full hover:bg-black transition-colors"
          >
            Reload App
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

// ID Generator Helper
const generateId = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return Date.now().toString(36) + Math.random().toString(36).substring(2);
};

// Main App Component
function AppContent() {
  const [view, setView] = useState<'dashboard' | 'history' | 'result' | 'saved'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [loadingMode, setLoadingMode] = useState<'feed' | 'url'>('feed');
  const [articles, setArticles] = useState<Article[]>([]);
  const [history, setHistory] = useState<DigestHistoryItem[]>([]);

  const [savedArticles, setSavedArticles] = useState<Article[]>([]);
  const [likedArticles, setLikedArticles] = useState<Article[]>([]);
  const [dislikedArticles, setDislikedArticles] = useState<Article[]>([]);
  const [isFallbackMode, setIsFallbackMode] = useState(false);

  const [config, setConfig] = useState<DigestConfig>({
    level: 'Mid-Level',
    topics: ['Random/Surprise Me'],
    dateRange: 'Last Month'
  });

  useEffect(() => {
    // Load local data
    try {
      const h = localStorage.getItem('ddd_history');
      if (h) setHistory(JSON.parse(h));
      const s = localStorage.getItem('ddd_saved');
      if (s) setSavedArticles(JSON.parse(s));
      const l = localStorage.getItem('ddd_liked');
      if (l) setLikedArticles(JSON.parse(l));
      const d = localStorage.getItem('ddd_disliked');
      if (d) setDislikedArticles(JSON.parse(d));
    } catch (e) {
      console.error("Storage error:", e);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('ddd_history', JSON.stringify(history));
    localStorage.setItem('ddd_saved', JSON.stringify(savedArticles));
    localStorage.setItem('ddd_liked', JSON.stringify(likedArticles));
    localStorage.setItem('ddd_disliked', JSON.stringify(dislikedArticles));
  }, [history, savedArticles, likedArticles, dislikedArticles]);

  const handleGenerateDigest = async () => {
    setLoading(true);
    setLoadingMode('feed');
    setView('result');
    setArticles([]); 
    setIsFallbackMode(false);

    try {
      const { fetchLiveDigest } = await import('./services/geminiService.ts');
      const results = await fetchLiveDigest(config, { likedArticles, dislikedArticles });

      if (results === FALLBACK_ARTICLES) {
        setIsFallbackMode(true);
      }

      setArticles(results);

      const historyItem: DigestHistoryItem = {
        id: generateId(),
        timestamp: Date.now(),
        config,
        articles: results,
        type: 'feed'
      };
      setHistory(prev => [historyItem, ...prev]);
    } catch (err) {
      console.error("Fetch failed:", err);
      alert("Briefing generation failed. Please check your internet connection or verify your API key.");
    } finally {
      setLoading(false);
    }
  };

  const handleAnalyzeUrl = async (url: string) => {
    setLoading(true);
    setLoadingMode('url');
    setView('result');
    setArticles([]);
    setIsFallbackMode(false);

    try {
      const { analyzeUrl } = await import('./services/geminiService.ts');
      const result = await analyzeUrl(url);
      setArticles([result]);

      const historyItem: DigestHistoryItem = {
        id: generateId(),
        timestamp: Date.now(),
        config: { level: config.level, topics: [], dateRange: 'Any Time' }, 
        articles: [result],
        type: 'url'
      };
      setHistory(prev => [historyItem, ...prev]);
    } catch (err) {
      console.error("Analysis failed:", err);
      alert("URL Analysis failed.");
    } finally {
      setLoading(false);
    }
  };

  const handleToggleSave = (article: Article) => {
    setSavedArticles(prev => prev.some(a => a.url === article.url) 
      ? prev.filter(a => a.url !== article.url) 
      : [article, ...prev]
    );
  };

  const handleRate = (article: Article, rating: 'up' | 'down' | null) => {
    setLikedArticles(prev => prev.filter(a => a.url !== article.url));
    setDislikedArticles(prev => prev.filter(a => a.url !== article.url));
