              className={`p-2.5 rounded-full transition-all duration-300 ${
                view === 'history' 
                  ? 'bg-white/80 text-charcoal shadow-sm ring-1 ring-black/5' 
                  : 'text-stone-500 hover:text-stone-800 hover:bg-white/40'
              }`}
