import { GoogleGenAI, Type } from "@google/genai";
import { Article, DigestConfig, UserPreferences } from "../types.ts";
import { FALLBACK_ARTICLES } from "../constants.ts";

// Switched to Flash model for faster inference and tool use
const MODEL_NAME = 'gemini-3-flash-preview';

const getPreferenceContext = (prefs?: UserPreferences): string => {
  if (!prefs) return "";
  let context = "";
  if (prefs.likedArticles.length > 0) {
    const likedTitles = prefs.likedArticles.slice(0, 5).map(a => `"${a.title}"`).join(", ");
    context += `USER FEEDBACK - POSITIVE: User liked: ${likedTitles}. Prioritize similar quality/depth.\n`;
  }
  if (prefs.dislikedArticles.length > 0) {
    const dislikedTitles = prefs.dislikedArticles.slice(0, 5).map(a => `"${a.title}"`).join(", ");
    context += `USER FEEDBACK - NEGATIVE: User disliked: ${dislikedTitles}. Avoid similar content.\n`;
  }
  return context;
};

const articleSchema = {
    type: Type.OBJECT,
    properties: {
        id: { type: Type.STRING },
        title: { type: Type.STRING },
        author: { type: Type.STRING },
        source: { type: Type.STRING },
        type: { type: Type.STRING },
        category: { type: Type.STRING },
        url: { type: Type.STRING },
        date: { type: Type.STRING },
        summary: { type: Type.ARRAY, items: { type: Type.STRING } },
        insights: { type: Type.ARRAY, items: { type: Type.STRING } },
        application_tips: { type: Type.ARRAY, items: { type: Type.STRING } },
        tweet_draft: { type: Type.STRING }
    },
    required: ["id", "title", "author", "source", "type", "category", "url", "summary", "insights", "application_tips"],
};

export async function fetchLiveDigest(config: DigestConfig, prefs?: UserPreferences): Promise<Article[]> {
  // Use API Key exclusively from environment
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const { level, topics, dateRange } = config;

  const topicsStr = topics.join(", ");
  const preferenceContext = getPreferenceContext(prefs);

  const prompt = `
    ACT AS: A World-Class Senior Product Design Lead and Curator.
    TASK: Find 4 unique, high-quality design articles or videos.

    STRICT CONSTRAINTS:
    1. DATE: Published within ${dateRange}.
    2. LEVEL: ${level} (If Senior: avoid generic 101 content, look for deep dives, case studies, and strategy).
    3. TOPICS: ${topicsStr}.
    4. QUALITY: Sources must be reputable (e.g., NNGroup, A List Apart, Smashing Mag, Case Studies, Substack leaders).
    ${preferenceContext}

    OUTPUT FORMAT: Return a valid JSON array of 4 Article objects. 
    IMPORTANT: For EVERY article, you MUST generate EXACTLY 5 distinct 'insights' and EXACTLY 5 distinct 'application_tips'.
    Use Google Search to find ACTUAL, CURRENT URLs.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
            type: Type.ARRAY,
            items: articleSchema
        },
        thinkingConfig: { thinkingBudget: 0 }
      },
    });

    const text = response.text;
    if (!text) return FALLBACK_ARTICLES;
    const cleanText = text.replace(/```json\n?|\n?```/g, '').trim();
    return JSON.parse(cleanText) as Article[];
  } catch (error) {
    console.error("Gemini fetch failed:", error);
    return FALLBACK_ARTICLES;
  }
}

export async function analyzeUrl(url: string): Promise<Article> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const isYoutube = url.toLowerCase().includes('youtube') || url.toLowerCase().includes('youtu.be');

  let contextInstruction = "";
  if (isYoutube) {
    contextInstruction = `
      CONTEXT: This is a YouTube video URL.
      CRITICAL: You MUST use Google Search to find the *actual* video title, description, and transcript/content.
      - Query suggestion: "summary of youtube video ${url}" or search for the video ID.
      - Do not hallucinate. If you cannot find the specific video content via search, state that in the summary.
      - 'application_tips' should be step-by-step instructions derived from the video content.
      - Ensure the 'type' field is set to 'Video'.
    `;
  } else {
    contextInstruction = `
      CONTEXT: This is a web article.
      CRITICAL: You MUST use Google Search to find the *actual* article content.
      - Verify the content matches the URL.
      - Extract the core content.
      - Ensure the 'type' field is set to 'Article'.
    `;
  }

  const prompt = `
    Analyze this specific URL: ${url}

    Act as a Product Designer & Technical Lead. 
    Your goal is to accurately extract the content from the provided URL and analyze it.

    ${contextInstruction}

    REQUIREMENTS:
    1. Summary: 3 concise paragraphs describing the actual content found.
    2. Insights: Extract EXACTLY 5 distinct core insights.
    3. Application Tips: Generate EXACTLY 5 actionable, practical steps.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: { 
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: articleSchema,
      },
    });

    const text = response.text;
    if (!text) throw new Error("Empty response");
    const cleanText = text.replace(/```json\n?|\n?```/g, '').trim();
    return JSON.parse(cleanText) as Article;
  } catch (error) {
    console.error("Analysis failed:", error);
    throw error;
  }
}

import React, { useState, useEffect, ErrorInfo, ReactNode, Component } from 'react';
import { DigestConfig, Article, DigestHistoryItem } from './types.ts';
import DigestConfigurator from './components/DigestConfigurator.tsx';
import ArticleCard from './components/ArticleCard.tsx';
import UrlAnalyzer from './components/UrlAnalyzer.tsx';
import SkeletonLoader from './components/SkeletonLoader.tsx';
import { History, Bookmark, Home, AlertTriangle, Link, Tag, ChevronRight, Filter } from 'lucide-react';
import { FALLBACK_ARTICLES } from './constants.ts';

// --- Error Boundary Component ---
interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

// Fixed: Explicitly extend Component with constructor to resolve prop typing issues
class SimpleErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = {
      hasError: false,
      error: null
    };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("ErrorBoundary caught an error", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="p-8 text-center min-h-screen flex flex-col items-center justify-center bg-[#FEFBF6]">
          <h2 className="text-2xl font-bold text-red-600 mb-2">Something went wrong.</h2>
          <p className="text-stone-600 mb-4">Please try refreshing the page.</p>
          <pre className="text-xs bg-white border border-stone-200 p-4 rounded text-left overflow-auto max-w-lg w-full">
            {this.state.error?.toString()}
          </pre>
          <button 
            onClick={() => window.location.reload()}
            className="mt-6 px-6 py-2 bg-charcoal text-white rounded-full hover:bg-black transition-colors"
          >
            Reload App
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

// ID Generator Helper
const generateId = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return Date.now().toString(36) + Math.random().toString(36).substring(2);
};

// Main App Component
function AppContent() {
  const [view, setView] = useState<'dashboard' | 'history' | 'result' | 'saved'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [loadingMode, setLoadingMode] = useState<'feed' | 'url'>('feed');
  const [articles, setArticles] = useState<Article[]>([]);
  const [history, setHistory] = useState<DigestHistoryItem[]>([]);

  const [savedArticles, setSavedArticles] = useState<Article[]>([]);
  const [likedArticles, setLikedArticles] = useState<Article[]>([]);
  const [dislikedArticles, setDislikedArticles] = useState<Article[]>([]);
  const [isFallbackMode, setIsFallbackMode] = useState(false);

  const [config, setConfig] = useState<DigestConfig>({
    level: 'Mid-Level',
    topics: ['Random/Surprise Me'],
    dateRange: 'Last Month'
  });

  useEffect(() => {
    // Load local data
    try {
      const h = localStorage.getItem('ddd_history');
      if (h) setHistory(JSON.parse(h));
      const s = localStorage.getItem('ddd_saved');
      if (s) setSavedArticles(JSON.parse(s));
      const l = localStorage.getItem('ddd_liked');
      if (l) setLikedArticles(JSON.parse(l));
      const d = localStorage.getItem('ddd_disliked');
      if (d) setDislikedArticles(JSON.parse(d));
    } catch (e) {
      console.error("Storage error:", e);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('ddd_history', JSON.stringify(history));
    localStorage.setItem('ddd_saved', JSON.stringify(savedArticles));
    localStorage.setItem('ddd_liked', JSON.stringify(likedArticles));
    localStorage.setItem('ddd_disliked', JSON.stringify(dislikedArticles));
  }, [history, savedArticles, likedArticles, dislikedArticles]);

  const handleGenerateDigest = async () => {
    setLoading(true);
    setLoadingMode('feed');
    setView('result');
    setArticles([]); 
    setIsFallbackMode(false);

    try {
      const { fetchLiveDigest } = await import('./services/geminiService.ts');
      const results = await fetchLiveDigest(config, { likedArticles, dislikedArticles });

      if (results === FALLBACK_ARTICLES) {
        setIsFallbackMode(true);
      }

      setArticles(results);

      const historyItem: DigestHistoryItem = {
        id: generateId(),
        timestamp: Date.now(),
        config,
        articles: results,
        type: 'feed'
      };
      setHistory(prev => [historyItem, ...prev]);
    } catch (err) {
      console.error("Fetch failed:", err);
      // Even if it fails, we might want to show fallback if not already handled
      setIsFallbackMode(true); 
      setArticles(FALLBACK_ARTICLES);
    } finally {
      setLoading(false);
    }
  };

  const handleAnalyzeUrl = async (url: string) => {
    setLoading(true);
    setLoadingMode('url');
    setView('result');
    setArticles([]);
    setIsFallbackMode(false);

    try {
      const { analyzeUrl } = await import('./services/geminiService.ts');
      const result = await analyzeUrl(url);
      setArticles([result]);

      const historyItem: DigestHistoryItem = {
        id: generateId(),
        timestamp: Date.now(),
        config: { level: config.level, topics: [], dateRange: 'Any Time' }, 
        articles: [result],
        type: 'url'
      };
      setHistory(prev => [historyItem, ...prev]);
    } catch (err) {
      console.error("Analysis failed:", err);
      alert("URL Analysis failed. Please check your API key and URL.");
      setView('dashboard'); // Go back on error
