      : [article, ...prev]
    );
  };

  const handleRate = (article: Article, rating: 'up' | 'down' | null) => {
    setLikedArticles(prev => prev.filter(a => a.url !== article.url));
    setDislikedArticles(prev => prev.filter(a => a.url !== article.url));
